window.GDD_CONTENU = {"catalogue":{"id":"ups-gdd","version":"0.1.1","titre":"La donnée, une affaire collective","sousTitre":"Sensibilisation à la gouvernance de la donnée","institution":"Université Paris-Saclay","introduction":"Tous les jours, tu saisis, consultes, transmets ou corriges des données : un dossier d'agent, une inscription, un prêt de livre, une facture, une intervention technique. Cette formation t'aide à comprendre pourquoi ces gestes comptent pour tout l'établissement, et quels réflexes simples permettent de mieux travailler ensemble.","public":"Personnels administratifs et techniques, quel que soit le service. Aucune connaissance préalable n'est nécessaire.","objectifs":["Expliquer simplement ce qu'est une donnée et ce qu'est la gouvernance de la donnée.","Comprendre pourquoi tes activités quotidiennes sont concernées.","Identifier les conséquences d'une donnée incorrecte ou mal structurée.","Comprendre l'intérêt de règles, de référentiels et de responsabilités communes.","Distinguer partage responsable des données et accès indiscriminé.","Reconnaître les bons réflexes professionnels."],"modules":[{"id":"m01","numero":1,"etat":"disponible","fichier":"module-01.json","titre":"La donnée dans mon quotidien"},{"id":"m02","numero":2,"etat":"disponible","fichier":"module-02.json","titre":"Une donnée, plusieurs usages"},{"id":"m03","numero":3,"etat":"disponible","fichier":"module-03.json","titre":"La qualité et la structuration des données"},{"id":"m04","numero":4,"etat":"disponible","fichier":"module-04.json","titre":"Partager sans perdre le contrôle"},{"id":"m05","numero":5,"etat":"disponible","fichier":"module-05.json","titre":"Qui organise les données ?"},{"id":"m06","numero":6,"etat":"disponible","fichier":"module-06.json","titre":"Les bons réflexes professionnels"},{"id":"m07","numero":7,"etat":"disponible","fichier":"module-07.json","titre":"Validation et consolidation des acquis"}],"carnet":{"titre":"Les données en jeu","interrupteur":"Les données en jeu","vide":"Aucune donnée en jeu pour l'instant. Elles apparaîtront quand tu auras fait un choix.","misAJour":"Une donnée a bougé","trace":"Ta trace","etat":"Après ton choix","fermer":"Fermer","donnees":[{"id":"affectations","titre":"Affectations des agents","module":1,"depuis":"m01-l1","creee":"Julie · ressources humaines · fichier des agents","reprises":"Sophie s'en sert pour la liste des agents par service.","absente":"Elle n'est pas chez Noé, tant que personne ne la lui transmet."},{"id":"pret","titre":"Prêt d'ouvrage","module":1,"depuis":"m01-l2","creee":"Karim · bibliothèque · tableau des relances","reprises":"Le prêt sert à relancer les retards, à la bibliothèque.","absente":"Il ne remonte pas aux ressources humaines."},{"id":"intervention","titre":"Intervention du bâtiment C","module":1,"depuis":"m01-l3","creee":"Noé · maintenance · logiciel de suivi des interventions","reprises":"Sophie la cherche pour savoir si la salle est utilisable.","absente":"Elle n'existe pas à la bibliothèque."},{"id":"arrivee-camille","titre":"Arrivée de Camille","module":2,"depuis":"m02-l1","creee":"Julie · ressources humaines · dossier agent","reprises":"Elle sert à Sophie pour le bureau, et peut servir à préparer les accès.","absente":"Karim ne la recrée pas : il cherche le nom déjà enregistré."},{"id":"catalogue-biblio","titre":"Catalogue de la bibliothèque","module":2,"depuis":"m02-l3","creee":"Karim · bibliothèque · catalogue d'ouvrages","reprises":"Sophie peut s'en servir pour un inventaire, dans un cadre défini.","absente":"L'historique des prêts ne quitte pas la bibliothèque."},{"id":"identite","titre":"Identité de Camille","module":3,"depuis":"m03-l3","creee":"Plusieurs services ont recopié son nom, chacun à sa façon.","reprises":"Un identifiant permet de voir qu'il s'agit de la même personne.","absente":"Sans identifiant, on ne sait pas si les libellés désignent une ou plusieurs personnes."},{"id":"salle","titre":"Salle et effectif","module":4,"depuis":"m04-l1","creee":"Sophie · gestion des salles · numéro de salle","reprises":"Noé ou la logistique peuvent avoir besoin d'un effectif, pas des noms.","absente":"Les noms des participants ne sont pas nécessaires pour préparer la salle."},{"id":"remunerations","titre":"Rémunérations","module":4,"depuis":"m04-l1","creee":"Julie · ressources humaines · dossier de paie","reprises":"Elles ne servent qu'aux personnes habilitées.","absente":"Elles ne sont ni à la bibliothèque, ni à la maintenance."},{"id":"sante","titre":"Informations de santé","module":4,"depuis":"m04-l4","creee":"Service de santé · dossier médical","reprises":"Les aménagements se prévoient sans le détail médical.","absente":"Elles ne circulent pas vers les autres services."},{"id":"inventaire-batiments","titre":"Inventaire des bâtiments","module":6,"depuis":"m06-l1","creee":"Noé · maintenance · inventaire des bâtiments","reprises":"Sophie peut s'en servir pour organiser une intervention.","absente":"Un nouveau tableau n'existe que si quelqu'un le crée à côté."},{"id":"effectifs-etudiants","titre":"Effectifs étudiants","module":6,"depuis":"m06-l4","creee":"Scolarité · tableau des effectifs par formation","reprises":"Le service finances et pilotage peut s'en servir si la date et le périmètre sont indiqués.","absente":"Sans ces précisions, le chiffre ne peut pas être comparé à un autre."}]},"testeurs":[{"id":"christophe","nom":"Christophe"},{"id":"marion","nom":"Marion"},{"id":"frederique","nom":"Frédérique"},{"id":"testeur-4","nom":"Testeur 4"},{"id":"testeur-5","nom":"Testeur 5"},{"id":"testeur-6","nom":"Testeur 6"},{"id":"testeur-7","nom":"Testeur 7"},{"id":"testeur-8","nom":"Testeur 8"},{"id":"testeur-9","nom":"Testeur 9"},{"id":"testeur-10","nom":"Testeur 10"}],"reconnaissance":{"titre":"Sensibilisation à la gouvernance de la donnée","moduleFinal":"m07","conditions":{"tousLesModules":true,"reussiteModuleFinal":true},"mention":"Reconnaissance indicative, calculée dans ce navigateur : ce n'est ni une attestation officielle, ni une certification d'expertise en gouvernance des données ou en RGPD. L'attribution éventuelle d'un badge institutionnel relève de la plateforme de formation, selon les règles validées par l'établissement."}},"modules":{"m01":{"id":"m01","numero":1,"titre":"La donnée dans mon quotidien","duree":10,"statutContenu":"proposition - à valider","objectif":"Reconnaître les données manipulées dans tes activités professionnelles.","objectifsSpecifiques":[{"id":"os1-1","texte":"Distinguer une donnée d'une information."},{"id":"os1-2","texte":"Reconnaître une donnée personnelle et une donnée métier."},{"id":"os1-3","texte":"Identifier les supports et les applications où les données sont enregistrées."}],"validation":{"navigation":"sequentielle","leconsObligatoires":true,"evaluation":"m01-quiz","seuilReussite":70},"lecons":[{"id":"m01-l1","type":"lecon","titre":"Des données partout dans mon travail","blocs":[{"type":"situation","texte":"Lundi matin. Julie, au service des ressources humaines, te transmet un fichier : les noms, prénoms et affectations des agents. Parmi eux, Karim à la bibliothèque, Noé à la maintenance, Sophie à la gestion des salles. Tu dois préparer la liste des agents par service pour organiser une réunion."},{"type":"decision","id":"m01-d1","consigne":"Pour préparer la liste des agents par service, que fais-tu ?","donnee":"affectations","choix":[{"id":"a","texte":"J'organise les données du fichier que Julie m'a transmis.","implication":"Tu t'appuies sur la donnée créée par Julie. Elle reste à un seul endroit, et Sophie peut s'en servir pour la réunion.","etat":"Tu t'appuies sur le fichier de Julie. Pas de copie en plus."},{"id":"b","texte":"Je recopie les noms dans un tableau personnel.","implication":"Une seconde copie apparaît sur ton bureau. Elle n'est pas reliée au fichier de Julie : si une affectation change, ton tableau ne le saura pas.","trace":"Ton tableau des agents, copie non reliée au fichier de Julie.","etat":"La même liste existe en deux endroits."}]},{"type":"visuel","titre":"Ce que tu viens de manipuler","chapo":"Tu as utilisé des données. Une fois organisées, elles deviennent une information utile.","etapes":[{"titre":"Données","texte":"Noms, prénoms, services","groupes":[{"teinte":"personne","elements":["Karim","Noé","Sophie"]},{"teinte":"service","elements":["Bibliothèque","Maintenance","Salles"]}]},{"titre":"Organisation","texte":"On relie les personnes à leur service.","liens":["Karim","Noé","Sophie"]},{"titre":"Information utile","texte":"Répondre à une question précise.","question":"Qui travaille dans quel service ?","tableau":{"colonnes":["Nom","Service"],"lignes":[["Karim","Bibliothèque"],["Noé","Maintenance"],["Sophie","Salles"]]}}]},{"type":"definition","entrees":[{"terme":"Donnée","formule":"élément brut","icone":"document","texte":"Un élément brut enregistré : un nom, une date, un montant, un code, un nombre. Elle peut être écrite sur papier, saisie dans un tableur ou enregistrée dans une application."},{"terme":"Information","formule":"données organisées pour agir","icone":"graphe","texte":"Ce que l'on obtient en interprétant des données dans un contexte, pour répondre à une question ou prendre une décision."}]},{"type":"visuel","variante":"services","titre":"La même logique dans tous les services","cas":[{"service":"Ressources humaines","donnees":["Date d'entrée","Grade","Affectation"],"information":"« 12 agents du service pourront partir à la retraite d'ici deux ans. »"},{"service":"Bibliothèque","donnees":["Code-barres d'un ouvrage","Date de prêt","Date de retour"],"information":"« 40 ouvrages sont en retard ce mois-ci. »"},{"service":"Maintenance","donnees":["Numéro de salle","Type d'équipement","Date de la dernière intervention"],"information":"« Le chauffage du bâtiment B doit être révisé avant l'hiver. »"},{"service":"Scolarité","donnees":["Numéro étudiant","Formation","Date d'inscription"],"information":"« La licence 1 compte 30 inscrits de plus que l'an dernier. »"}]},{"type":"activite","ref":"m01-a1"},{"type":"aretenir","texte":"**Une donnée est un élément brut enregistré.** **Une information naît quand on interprète des données pour répondre à une question.** Ton travail quotidien produit et utilise les deux."}]},{"id":"m01-l2","type":"lecon","titre":"Données métier et données personnelles","blocs":[{"type":"situation","texte":"À la bibliothèque, Karim prépare les relances pour les ouvrages en retard. Son tableau contient le titre des livres, la date de retour prévue… mais aussi le nom et l'adresse électronique des lecteurs. L'un d'eux est un agent dont Julie a déjà enregistré l'identité."},{"type":"decision","id":"m01-d2","consigne":"Karim prépare une relance. Qu'est-ce qui part dans le message ?","donnee":"pret","choix":[{"id":"a","texte":"Le titre de l'ouvrage et la date de retour prévue.","implication":"La relance peut se faire. Le nom et le mél du lecteur restent dans l'outil de la bibliothèque.","etat":"Le prêt reste à la bibliothèque. Le nom du lecteur n'est pas repris dans la relance."},{"id":"b","texte":"Le titre, la date, le nom du lecteur et son adresse électronique.","implication":"La relance identifie la personne. Ces données personnelles quittent le tableau pour un message, qui peut être transféré.","trace":"Nom et mél du lecteur repris dans la relance.","etat":"Une donnée personnelle est jointe au prêt."}]},{"type":"visuel","variante":"regards","titre":"Deux façons de regarder une donnée","chapo":"Une même donnée peut être métier, personnelle… ou les deux.","regards":[{"terme":"Donnée métier","texte":"Utilisée pour l'activité de l'établissement.","exemple":"nombre de livres prêtés","icone":"mallette","teinte":"metier"},{"terme":"Donnée personnelle","texte":"Se rapporte à une personne identifiée ou identifiable.","exemple":"nom, photo, n° étudiant","icone":"personne","teinte":"personne"}],"commun":{"titre":"Les deux à la fois","texte":"Le nom d'un étudiant associé à l'emprunt d'un livre"}},{"type":"definition","entrees":[{"terme":"Donnée métier","formule":"utilisée pour l'activité de l'établissement","icone":"mallette","texte":"Une donnée produite ou utilisée pour réaliser une activité de l'établissement : inscrire un étudiant, payer une facture, prêter un livre, planifier une intervention."},{"terme":"Donnée personnelle","formule":"personne identifiée ou identifiable","icone":"personne","texte":"Toute information se rapportant à une personne physique identifiée ou identifiable, directement (un nom, une photo) ou indirectement (un numéro étudiant, un identifiant de connexion, ou plusieurs données croisées entre elles)."}]},{"type":"exemple","titre":"Attention aux identifications indirectes","texte":"« Le seul agent de catégorie A du service, arrivé en 2019 » : aucun nom n'est écrit, et pourtant toute l'équipe sait de qui il s'agit. C'est donc bien une donnée personnelle."},{"type":"texte","titre":"Pas interdites, mais à manier avec attention","texte":"Les données personnelles ne sont pas interdites : sans elles, impossible de payer les agents ou d'inscrire les étudiants. Elles demandent simplement plus d'attention : on les protège et on les utilise pour la mission prévue. Le module 4 y revient en détail."},{"type":"activite","ref":"m01-a2"},{"type":"aretenir","texte":"**Les données personnelles sont des données qui permettent d'identifier quelqu'un, même indirectement.** Elles sont souvent indispensables au travail : **elles ne sont pas interdites, elles demandent de l'attention.**"}]},{"id":"m01-l3","type":"lecon","titre":"Où vivent les données ?","blocs":[{"type":"situation","texte":"Noé est passé sur la chaudière du bâtiment C. Sophie doit savoir quand elle a été révisée, pour dire si la salle est utilisable. Elle trouve une date dans un tableur partagé, une autre dans un courriel, et une troisième dans le logiciel de suivi des interventions. Laquelle croire ?"},{"type":"decision","id":"m01-d3","consigne":"Sophie te demande quoi noter pour la chaudière. Que fais-tu ?","donnee":"intervention","choix":[{"id":"a","texte":"Je recopie la date du courriel.","implication":"Le courriel fige une date à un instant donné. Elle peut déjà être fausse, et une quatrième copie vient de naître.","trace":"Date du courriel recopiée pour la chaudière du bâtiment C.","etat":"La date est douteuse : elle ne vient pas de l'outil de Noé."},{"id":"b","texte":"Je retiens la date du logiciel de suivi des interventions.","implication":"C'est l'outil où Noé enregistre ses passages. Sophie s'appuie sur cette source, et peut signaler l'écart des autres copies.","etat":"La date retenue est celle du logiciel de suivi, tenu par Noé."},{"id":"c","texte":"Je laisse le champ vide et je signale que trois dates circulent.","implication":"Rien n'est inventé. L'écart reste visible, le temps que Noé confirme la date qui fait référence.","etat":"La date manque, et l'écart entre les trois supports est signalé."}]},{"type":"texte","titre":"Support et application","texte":"Une donnée est toujours enregistrée quelque part : c'est son **support de stockage**. Elle peut aussi être gérée par une **application**, c'est-à-dire un logiciel conçu pour une activité précise, qui encadre la saisie et organise les données."},{"type":"tableau","titre":"Les principaux supports","colonnes":["Support","Exemples","Point d'attention"],"lignes":[["Papier","Dossier, registre, formulaire signé","Difficile à partager et à mettre à jour."],["Fichier bureautique","Tableur, document texte","Facile à copier, donc vite multiplié en versions différentes."],["Messagerie","Pièce jointe, contenu d'un courriel","La donnée y reste figée et devient difficile à retrouver."],["Application de gestion","Logiciel RH, de scolarité, de bibliothèque, de suivi des interventions","Elle prévoit des règles de saisie, des droits d'accès et un historique."]]},{"type":"exemple","titre":"Ce qui s'est passé pour Sophie","texte":"Noé a enregistré son passage. Ensuite, la date a été recopiée dans un tableur et dans un courriel. Trois supports, trois versions. Personne n'a commis de faute : chaque copie a vécu sa vie. C'est l'une des difficultés que la gouvernance de la donnée aide à résoudre."},{"type":"activite","ref":"m01-a3"},{"type":"activite","ref":"m01-a4"},{"type":"aretenir","texte":"Une même donnée peut exister sur plusieurs supports. Quand les copies se multiplient, elles finissent par diverger : il faut savoir quelle source fait référence."}]},{"id":"m01-quiz","type":"evaluation","titre":"Quiz du module","introduction":"Quatre questions pour faire le point. Il n'y a pas de limite de temps et tu pourras recommencer si tu le souhaites. Le seuil de réussite est de 70 %.","activites":["m01-q1","m01-q2","m01-q3","m01-q4"]}],"activites":{"m01-a1":{"type":"choix-multiple","objectif":"os1-1","notation":{"formative":true,"points":1},"consigne":"Parmi ces éléments, lesquels sont des données brutes ?","choix":[{"id":"a","texte":"La date de naissance d'un agent"},{"id":"b","texte":"Le numéro d'inventaire d'un ordinateur"},{"id":"c","texte":"Le montant d'une facture"},{"id":"d","texte":"Le constat « les retards de paiement ont doublé cette année »"}],"reponses":["a","b","c"],"explication":{"correct":"Exactement. Une date, un numéro ou un montant sont des éléments bruts enregistrés. Le constat sur les retards de paiement est une information : il a fallu comparer de nombreuses données pour l'obtenir.","incorrect":"Pas tout à fait. Une date, un numéro ou un montant sont des données brutes. En revanche, « les retards de paiement ont doublé » est une information : elle résulte de l'analyse de nombreuses données."}},"m01-a2":{"type":"classement","objectif":"os1-2","notation":{"formative":true,"points":1},"consigne":"Pour chaque donnée, indique s'il s'agit d'une donnée personnelle ou non.","categories":[{"id":"p","texte":"Donnée personnelle"},{"id":"n","texte":"Donnée non personnelle"}],"elements":[{"id":"1","texte":"Le numéro étudiant d'une inscrite","categorie":"p","explication":"Il permet de retrouver une personne précise : c'est une identification indirecte."},{"id":"2","texte":"Le numéro d'une salle de cours","categorie":"n","explication":"Il désigne un lieu, pas une personne."},{"id":"3","texte":"L'adresse électronique professionnelle prenom.nom d'un agent","categorie":"p","explication":"Même professionnelle, elle identifie directement une personne."},{"id":"4","texte":"Le nombre total d'inscrits dans une formation de 200 étudiants","categorie":"n","explication":"C'est un total : il ne permet pas de remonter à une personne en particulier."},{"id":"5","texte":"La photo d'une collègue dans l'annuaire interne","categorie":"p","explication":"Une photo permet d'identifier directement une personne."},{"id":"6","texte":"Le numéro d'inventaire d'un vidéoprojecteur","categorie":"n","explication":"Il désigne un équipement, pas une personne."}],"explication":{"correct":"Bravo, ton classement est juste. Retiens qu'une donnée est personnelle dès qu'elle permet d'identifier quelqu'un, directement ou indirectement.","incorrect":"Certaines réponses sont à revoir. Une donnée est personnelle dès qu'elle permet d'identifier quelqu'un, directement (nom, photo) ou indirectement (numéro, identifiant)."}},"m01-a3":{"type":"vrai-faux","objectif":"os1-3","notation":{"formative":true,"points":1},"consigne":"Vrai ou faux : une donnée n'existe vraiment que si elle est enregistrée dans une application informatique.","reponse":false,"explication":{"correct":"C'est bien faux. Un formulaire papier, un tableur ou un courriel contiennent aussi des données. L'application apporte un cadre et des contrôles, mais ce n'est pas le seul support.","incorrect":"En réalité, c'est faux. Un formulaire papier, un tableur ou un courriel contiennent aussi des données. L'application apporte un cadre et des contrôles, mais ce n'est pas le seul support."}},"m01-a4":{"type":"choix-unique","objectif":"os1-3","notation":{"formative":true,"points":1},"consigne":"Pour connaître la date réelle de la dernière révision de la chaudière, quelle source Sophie devrait-elle consulter en priorité ?","choix":[{"id":"a","texte":"Le tableur partagé, car c'est le plus facile à consulter","feedback":"Le tableur est pratique, mais c'est souvent une copie : rien ne garantit qu'il soit à jour."},{"id":"b","texte":"Le logiciel de suivi des interventions, prévu pour enregistrer ces opérations","feedback":"C'est l'outil prévu pour cette activité : il fait en principe référence."},{"id":"c","texte":"Le courriel le plus récent","feedback":"Un courriel fige une donnée à un instant donné ; il n'est pas fait pour servir de référence."}],"reponse":"b","explication":{"correct":"L'outil prévu pour l'activité est en principe la source de référence. En cas de doute, Sophie peut vérifier auprès du technicien et signaler l'écart pour que les autres copies soient corrigées.","incorrect":"La meilleure option est le logiciel de suivi des interventions : c'est l'outil prévu pour enregistrer ces opérations. En cas de doute, Sophie peut vérifier auprès du technicien et signaler l'écart."}},"m01-q1":{"type":"choix-unique","objectif":"os1-1","notation":{"formative":false,"points":1},"consigne":"Un tableau indique, pour chaque agent, sa date d'arrivée dans l'établissement. Ta responsable te demande combien d'agents sont arrivés cette année. Le chiffre que tu lui donnes est…","choix":[{"id":"a","texte":"une donnée brute"},{"id":"b","texte":"une information obtenue à partir de données"},{"id":"c","texte":"une donnée personnelle"}],"reponse":"b","explication":{"correct":"Oui : tu as compté et interprété des dates pour répondre à une question. C'est une information.","incorrect":"La bonne réponse est « une information obtenue à partir de données » : tu as compté et interprété des dates d'arrivée pour répondre à une question."}},"m01-q2":{"type":"choix-multiple","objectif":"os1-2","notation":{"formative":false,"points":1},"consigne":"Lesquelles de ces données sont des données personnelles ?","choix":[{"id":"a","texte":"Le numéro étudiant"},{"id":"b","texte":"L'identifiant de connexion d'un agent"},{"id":"c","texte":"Le budget annuel du service"},{"id":"d","texte":"Les horaires d'ouverture de la bibliothèque"}],"reponses":["a","b"],"explication":{"correct":"Exact. Le numéro étudiant et l'identifiant de connexion permettent de retrouver une personne précise.","incorrect":"Les bonnes réponses sont le numéro étudiant et l'identifiant de connexion : ils permettent de retrouver une personne précise. Le budget et les horaires ne concernent personne en particulier."}},"m01-q3":{"type":"vrai-faux","objectif":"os1-2","notation":{"formative":false,"points":1},"consigne":"Vrai ou faux : les services ne doivent jamais utiliser de données personnelles.","reponse":false,"explication":{"correct":"C'est bien faux. Les données personnelles sont indispensables à de nombreuses missions (paie, inscriptions, prêts). Elles demandent de l'attention, pas une interdiction.","incorrect":"C'est faux : les données personnelles sont indispensables à de nombreuses missions (paie, inscriptions, prêts). Elles doivent être protégées et utilisées pour la mission prévue."}},"m01-q4":{"type":"choix-unique","objectif":"os1-3","notation":{"formative":false,"points":1},"consigne":"Tu trouves deux adresses différentes pour un même fournisseur : l'une dans un ancien tableur, l'autre dans l'application financière. Quel est le meilleur réflexe ?","choix":[{"id":"a","texte":"Utiliser l'adresse du tableur, que tu connais bien"},{"id":"b","texte":"Utiliser l'adresse de l'application financière et signaler l'écart à la personne qui gère le tableur"},{"id":"c","texte":"Créer un nouveau tableur contenant les deux adresses"}],"reponse":"b","explication":{"correct":"Oui. L'application prévue pour l'activité fait en principe référence, et signaler l'écart évite que l'erreur se propage.","incorrect":"Le meilleur réflexe est d'utiliser l'application financière, qui fait en principe référence, et de signaler l'écart. Un nouveau tableur ajouterait une copie de plus."}}},"synthese":["Une donnée est un élément brut ; une information est ce que l'on en tire pour répondre à une question.","Une donnée personnelle permet d'identifier quelqu'un, même indirectement. Elle n'est pas interdite : elle demande de l'attention.","Les données vivent sur différents supports. Quand les copies se multiplient, il faut savoir quelle source fait référence."]},"m02":{"id":"m02","numero":2,"titre":"Une donnée, plusieurs usages","sousTitre":"Comprendre comment les données circulent entre les services.","duree":8,"statutContenu":"proposition - à valider","objectif":"Une donnée peut être créée à un endroit, utilisée à plusieurs endroits et produire des conséquences au-delà du service qui l'a enregistrée.","objectifsSpecifiques":[{"id":"os2-1","texte":"Reconnaître qu'une donnée peut avoir plusieurs usages."},{"id":"os2-2","texte":"Identifier les services susceptibles d'utiliser une même information."},{"id":"os2-3","texte":"Comprendre comment une erreur de saisie ou une information non actualisée peut se propager."},{"id":"os2-4","texte":"Expliquer pourquoi la qualité des données concerne plusieurs acteurs."},{"id":"os2-5","texte":"Comprendre la donnée comme un patrimoine informationnel partagé, dont l'accès et la réutilisation doivent être encadrés."}],"validation":{"navigation":"sequentielle","leconsObligatoires":true,"evaluation":"m02-defi"},"lecons":[{"id":"m02-l1","type":"lecon","titre":"Une information peut servir plusieurs fois","blocs":[{"type":"situation","texte":"Camille rejoint l'université. Au service des ressources humaines, Julie enregistre son arrivée : son nom, son affectation, sa date d'arrivée et sa situation professionnelle.\n\nPour Julie, la saisie est terminée. Pour l'information, le parcours ne fait que commencer."},{"type":"schema","titre":"Où cette information peut-elle être utile ?","consigne":"Sélectionne chaque service pour découvrir pourquoi l'information lui est utile.","source":{"libelle":"Julie · RH","detail":"Saisie de l'arrivée de Camille"},"flux":"Information sur l'affectation","cibles":[{"id":"gestion","libelle":"Gestion administrative","usage":"Mise à jour du dossier","detail":"Le dossier administratif de l'agent doit refléter sa situation réelle : affectation, date d'arrivée, rattachement."},{"id":"informatique","libelle":"Informatique","usage":"Organisation des accès autorisés","detail":"L'affectation permet de préparer un compte et d'ouvrir les accès aux applications utiles à ses missions, et seulement à celles-ci."},{"id":"services-generaux","libelle":"Services généraux","usage":"Organisation des locaux","detail":"Savoir qui arrive et dans quelle structure aide à prévoir un bureau, un badge ou du matériel."},{"id":"pilotage","libelle":"Pilotage","usage":"Suivi des effectifs par structure","detail":"Additionnées, les affectations permettent de suivre les effectifs de chaque structure et d'éclairer les décisions."}],"legende":"Exemple illustratif : il ne décrit pas les circuits réels de l'Université Paris-Saclay."},{"type":"decision","id":"m02-d1","consigne":"Karim doit ouvrir une carte de lecteur pour Camille. Que fait-il ?","donnee":"arrivee-camille","choix":[{"id":"a","texte":"Il cherche le nom déjà enregistré par Julie.","implication":"L'identité existe déjà. Karim s'en sert, il ne la recrée pas. La bibliothèque a une carte, pas une seconde fiche.","etat":"Karim a recherché le nom de Camille. Il ne l'a pas ressaisi."},{"id":"b","texte":"Il retape le nom dans le catalogue de la bibliothèque.","implication":"Une seconde écriture vient de naître. Si Julie corrige une lettre, le catalogue de Karim gardera l'ancienne.","trace":"Nom de Camille retapé à la bibliothèque, sans lien avec le dossier de Julie.","etat":"Le nom de Camille existe en deux écritures."}]},{"type":"texte","titre":"Une saisie, plusieurs usages","texte":"La personne qui saisit une donnée ne connaît pas toujours tous les usages qui en seront faits ensuite. C'est normal : chaque service connaît d'abord ses propres besoins.\n\nC'est justement pour cela que des **règles communes** sont utiles : elles permettent à chacun de produire une information fiable, compréhensible et réutilisable par les autres."},{"type":"exemple","etiquette":"Point de vigilance","titre":"Partager ne veut pas dire tout ouvrir","texte":"Partager une information ne signifie pas que tout le monde peut accéder à tout. Chaque service n'a besoin que des informations utiles à ses missions : l'informatique a besoin de l'affectation pour ouvrir des accès, pas du dossier complet de l'agent."},{"type":"activite","ref":"m02-a1"},{"type":"aretenir","texte":"Une donnée peut être produite dans un service et être utile à d'autres."}]},{"id":"m02-l2","type":"lecon","titre":"Quand une erreur voyage","blocs":[{"type":"situation","texte":"Camille a changé de service : elle travaille désormais à la scolarité. Le dossier de Julie est à jour. Pourtant, le fichier local de Sophie, utilisé pour les bureaux, indique toujours l'ancienne affectation."},{"type":"chronologie","titre":"Suis le parcours de l'information","etapes":[{"titre":"Une information non actualisée","texte":"Le changement d'affectation a bien été pris en compte par le service concerné, mais le fichier local n'a pas été mis à jour. Personne ne s'en aperçoit."},{"titre":"Un fichier réutilisé","texte":"Quelques semaines plus tard, ce fichier sert de base à une extraction pour un tableau de suivi. L'ancienne affectation y est reprise telle quelle."},{"titre":"Un résultat incorrect","texte":"Le tableau présente une mauvaise répartition des effectifs : un service apparaît avec un agent de trop, la scolarité avec un agent de moins."},{"titre":"Plusieurs personnes doivent intervenir","texte":"Pour corriger, il faut :\n- retrouver l'origine de l'erreur ;\n- identifier l'information qui fait référence ;\n- corriger les différents supports qui ont repris l'erreur."}],"conclusion":"Une seule information non actualisée a mobilisé plusieurs personnes, dans plusieurs services, pour être corrigée."},{"type":"decision","id":"m02-d2","consigne":"Le fichier de Sophie indique encore l'ancienne affectation de Camille. Que fais-tu ?","donnee":"arrivee-camille","choix":[{"id":"a","texte":"Je corrige le fichier de Sophie à partir du dossier de Julie.","implication":"La source est le dossier agent. Le bureau de Sophie retrouve la même affectation que les ressources humaines.","etat":"L'affectation de Camille a été reprise depuis le dossier de Julie."},{"id":"b","texte":"Je mets à jour seulement le fichier local de Sophie.","implication":"Le bureau est juste pour aujourd'hui. Le dossier de Julie et le fichier local peuvent à nouveau diverger au prochain changement.","trace":"Fichier local de Sophie modifié sans revenir au dossier de Julie.","etat":"Deux affectations peuvent encore coexister."}]},{"type":"activite","ref":"m02-a2"},{"type":"texte","titre":"Pas une faute individuelle","texte":"Ce type de situation ne vient pas d'une personne négligente. Il s'explique souvent par :\n\n- des applications qui ne sont pas reliées entre elles ;\n- des procédures différentes d'un service à l'autre ;\n- un manque de règles communes ;\n- des informations qui circulent difficilement ;\n- des fichiers locaux qui ne sont pas synchronisés.\n\nLa gouvernance de la donnée aide à améliorer ces situations **collectivement**, en clarifiant les sources, les responsabilités et les circuits de mise à jour."},{"type":"aretenir","texte":"Une petite erreur peut avoir des conséquences importantes lorsqu'une donnée est réutilisée."}]},{"id":"m02-l3","type":"lecon","titre":"À qui appartient la donnée ?","blocs":[{"type":"situation","texte":"Karim gère le catalogue d'ouvrages de la bibliothèque. Sophie souhaite utiliser certaines informations bibliographiques pour un inventaire des salles de lecture. Comment réagir ?"},{"type":"activite","ref":"m02-a3","carnet":{"donnee":"catalogue-biblio","effets":{"a":{"trace":"Rien n'a été transmis, même les références qui auraient pu servir à Sophie.","etat":"Le catalogue reste à la bibliothèque. L'inventaire n'avance pas."},"b":{"etat":"Karim vérifie ce qui peut partir. L'historique des prêts reste à la bibliothèque."}}}},{"type":"texte","titre":"Un patrimoine informationnel partagé","texte":"Les données produites par un service peuvent avoir une valeur pour d'autres : elles forment un **patrimoine informationnel** de l'établissement.\n\nCela ne signifie pas pour autant :\n\n- que les données peuvent être diffusées librement ;\n- que les services perdent leurs responsabilités ;\n- que tout devient accessible à tout le monde ;\n- que les règles de confidentialité deviennent inutiles.\n\nLes services conservent leur expertise et leurs responsabilités sur les données qu'ils gèrent. Ce sont eux qui savent le mieux ce que contient l'information, ce qui peut être réutilisé et dans quelles conditions."},{"type":"aretenir","texte":"Les données peuvent être utiles à plusieurs services, tout en restant soumises à des responsabilités et des règles d'accès."}]},{"id":"m02-defi","type":"evaluation","titre":"Le défi du module","surtitre":"Défi final","libelleAcces":"Relever le défi","libelleRecommencer":"Recommencer le défi","presentation":"une-par-une","introduction":"Trois situations, une question à la fois. Tu découvres la correction après chaque réponse, et tu peux recommencer le défi autant de fois que tu le souhaites.","activites":["m02-q1","m02-q2","m02-q3"],"messagesResultat":[{"min":100,"texte":"Bravo ! Tu as bien identifié comment une information circule entre les services et pourquoi son partage doit être encadré."},{"min":60,"texte":"C'est un bon début. Relis la correction de la question à revoir : elle reprend un point clé du module."},{"min":0,"texte":"Ces notions sont nouvelles pour beaucoup de personnes. Prends le temps de relire les corrections et les points à retenir, puis recommence le défi quand tu le souhaites."}]}],"activites":{"m02-a1":{"type":"vrai-faux","objectif":"os2-1","notation":{"formative":true,"points":1},"consigne":"Vrai ou faux : une information saisie par le service RH ne sert qu'au service RH.","reponse":false,"explication":{"correct":"C'est bien faux. Comme dans l'exemple, une même information peut servir à la gestion administrative, à l'informatique, aux services généraux ou au pilotage, chacun pour ses propres missions.","incorrect":"En réalité, c'est faux. Une même information peut servir à plusieurs services, chacun pour ses propres missions : gestion administrative, informatique, services généraux, pilotage."}},"m02-a2":{"type":"choix-unique","objectif":"os2-3","notation":{"formative":true,"points":1},"consigne":"À quel moment le problème aurait-il pu être évité ou limité ?","choix":[{"id":"a","texte":"En vérifiant l'actualisation de l'information à sa source appropriée.","feedback":"Oui : avant de réutiliser une information, vérifier qu'elle est à jour à la bonne source limite la propagation de l'erreur."},{"id":"b","texte":"En interdisant à tous les autres services de produire des tableaux.","feedback":"Les tableaux de suivi sont utiles aux missions des services. Le problème ne vient pas du tableau, mais de l'information non actualisée qu'il a reprise."},{"id":"c","texte":"En créant systématiquement une nouvelle copie du fichier.","feedback":"Une copie de plus multiplie les versions : elle augmente le risque d'écart au lieu de le réduire."}],"reponse":"a","explication":{"correct":"Vérifier la bonne source, l'actualisation et la cohérence d'une information permet de limiter les erreurs qui peuvent se répercuter dans d'autres activités.","incorrect":"La meilleure réponse est de vérifier l'actualisation de l'information à sa source appropriée. Vérifier la bonne source, l'actualisation et la cohérence d'une information permet de limiter les erreurs qui peuvent se répercuter dans d'autres activités."}},"m02-a3":{"type":"choix-unique","objectif":"os2-5","notation":{"formative":true,"points":1},"consigne":"Deux réactions sont possibles à la bibliothèque. Laquelle te paraît la plus adaptée ?","choix":[{"id":"a","texte":"« Ces données appartiennent à notre service, nous devons les conserver exclusivement chez nous. »","feedback":"Cette réaction protège les données, mais elle prive l'établissement d'informations utiles à d'autres missions, alors qu'un partage encadré est souvent possible."},{"id":"b","texte":"« Ces informations pourraient être utiles à d'autres. Vérifions ce qui peut être réutilisé et dans quelles conditions. »","feedback":"Cette réaction reconnaît la valeur de l'information pour d'autres services, sans renoncer aux responsabilités de la bibliothèque."}],"reponse":"b","explication":{"correct":"Oui. La bibliothèque reste responsable de son catalogue : c'est elle qui sait ce qui peut être réutilisé et dans quelles conditions. Partager, c'est mettre à disposition ce qui est utile, dans un cadre adapté.","incorrect":"La réaction la plus adaptée est la seconde : vérifier ce qui peut être réutilisé et dans quelles conditions. La bibliothèque garde ses responsabilités, tout en permettant à l'information de servir à d'autres missions."}},"m02-q1":{"type":"choix-unique","objectif":"os2-2","notation":{"formative":false,"points":1},"consigne":"Une gestionnaire RH modifie l'affectation d'un agent. Pourquoi cette mise à jour peut-elle intéresser d'autres services ?","choix":[{"id":"a","texte":"Parce que tous les services doivent automatiquement recevoir l'intégralité du dossier."},{"id":"b","texte":"Parce que certains services peuvent avoir besoin de cette information pour leurs propres missions."},{"id":"c","texte":"Parce que le dossier doit être copié dans tous les tableaux Excel."}],"reponse":"b","explication":{"correct":"Une information telle que l'affectation peut être utile à plusieurs services, notamment pour leurs activités de gestion ou de pilotage. Sa transmission doit néanmoins respecter les finalités et les habilitations autorisées.","incorrect":"La bonne réponse est la deuxième. Une information telle que l'affectation peut être utile à plusieurs services, notamment pour leurs activités de gestion ou de pilotage. Sa transmission doit néanmoins respecter les finalités et les habilitations autorisées."}},"m02-q2":{"type":"choix-unique","objectif":"os2-4","notation":{"formative":false,"points":1},"consigne":"Un tableau de scolarité contient un code de formation incorrect. Ce tableau est ensuite repris dans un bilan. Quel est le principal risque ?","choix":[{"id":"a","texte":"Le résultat du bilan peut devenir incorrect."},{"id":"b","texte":"L'erreur concerne uniquement la personne ayant créé le tableau."},{"id":"c","texte":"Le logiciel doit obligatoirement être remplacé."}],"reponse":"a","explication":{"correct":"Une erreur peut se répercuter dans les tableaux, les statistiques ou les documents produits à partir d'une même information. Identifier et corriger la source appropriée aide à éviter sa répétition.","incorrect":"Le principal risque est que le bilan devienne incorrect. Une erreur peut se répercuter dans les tableaux, les statistiques ou les documents produits à partir d'une même information. Identifier et corriger la source appropriée aide à éviter sa répétition."}},"m02-q3":{"type":"choix-unique","objectif":"os2-5","notation":{"formative":false,"points":1},"consigne":"Le service maintenance gère l'inventaire des équipements. Un autre service souhaite disposer de certaines de ces informations pour préparer des travaux. Quelle attitude privilégier ?","choix":[{"id":"a","texte":"Refuser systématiquement, puisque l'inventaire est géré par la maintenance."},{"id":"b","texte":"Transmettre intégralement l'inventaire sans vérification."},{"id":"c","texte":"Identifier les informations nécessaires et vérifier les conditions de leur transmission."}],"reponse":"c","explication":{"correct":"Le partage responsable consiste à mettre à disposition les informations utiles, dans un cadre adapté aux missions et aux règles applicables.","incorrect":"L'attitude à privilégier est d'identifier les informations nécessaires et de vérifier les conditions de leur transmission. Le partage responsable consiste à mettre à disposition les informations utiles, dans un cadre adapté aux missions et aux règles applicables."}}},"synthese":["Une donnée peut être produite dans un service et être utile à d'autres.","Une petite erreur peut avoir des conséquences importantes lorsqu'une donnée est réutilisée : vérifier la bonne source et son actualisation limite sa propagation.","Les données forment un patrimoine informationnel partagé : elles peuvent servir à plusieurs services, tout en restant soumises à des responsabilités et à des règles d'accès."]},"m03":{"id":"m03","numero":3,"titre":"La qualité et la structuration des données","sousTitre":"Pourquoi certaines données sont faciles à utiliser et d'autres beaucoup moins.","slugArchive":"qualite-structuration","duree":10,"statutContenu":"proposition - à valider","objectif":"Comprendre pourquoi la manière de saisir, organiser et actualiser les données influence directement leur fiabilité, leur compréhension et leur réutilisation.","objectifsSpecifiques":[{"id":"os3-1","texte":"Reconnaître les principales caractéristiques d'une donnée de qualité."},{"id":"os3-2","texte":"Comprendre pourquoi des données structurées sont plus facilement exploitables."},{"id":"os3-3","texte":"Identifier les difficultés créées par des formats ou des nomenclatures incohérents."},{"id":"os3-4","texte":"Comprendre l'utilité d'un identifiant stable."},{"id":"os3-5","texte":"Reconnaître le rôle d'un référentiel commun."},{"id":"os3-6","texte":"Identifier les bons réflexes face à une information incomplète, ambiguë ou incorrecte."}],"validation":{"navigation":"sequentielle","leconsObligatoires":true,"evaluation":"m03-defi"},"lecons":[{"id":"m03-l1","type":"lecon","titre":"Deux tableaux, deux conséquences","blocs":[{"type":"situation","texte":"Julie te transmet la liste des agents inscrits à une session de formation : Camille, Karim, Noé.\n\nÀ première vue, tout y est… mais au moment de trier les inscriptions par date, plusieurs choses coincent."},{"type":"comparateur","titre":"Qu'est-ce qui rend ce tableau difficile à utiliser ?","consigne":"Sélectionne une cellule du tableau, ou une difficulté de la liste, pour comprendre ce qui pose problème. Examine les cinq difficultés.","avant":{"titre":"Tableau A : inscriptions reçues","colonnes":["Agent","Service","Date inscription"],"lignes":[["Camille Martin","RH","12/03/26"],["Karim Bernard","Ress. Humaines","2026-03-12"],["Noé Petit","DRH","13 mars 2026"],["Martin Camille","RH",""]],"legende":"Données fictives."},"problemes":[{"id":"dates","libelle":"Formats de date hétérogènes","explication":"Trois écritures pour une même information : un tri par date sera faux. Et « 12/03/26 » peut se lire 12 mars… ou 3 décembre.","cellules":[[0,2],[1,2],[2,2]]},{"id":"nom-prenom","libelle":"Nom et prénom réunis","explication":"Une seule colonne, et pas toujours le même ordre : « Camille Martin », mais « Karim Bernard ». Impossible de trier par nom, ni d'être sûr de savoir lequel est le prénom.","cellules":[[0,0],[1,0],[2,0],[3,0]]},{"id":"nomenclature","libelle":"Services désignés différemment","explication":"« RH », « Ress. Humaines », « DRH » : la même structure, ou pas ? Un comptage par service sera faux dans les deux cas si l'on se trompe. Seul le **référentiel des structures** permet de le savoir.","cellules":[[0,1],[1,1],[2,1],[3,1]]},{"id":"manquante","libelle":"Une donnée manquante","explication":"La dernière date n'est pas renseignée. On ne l'invente pas : on la retrouve à la bonne source, ou on signale qu'elle manque.","cellules":[[3,2]]},{"id":"doublon","libelle":"Un risque de doublon","explication":"« Camille Martin » et « Martin Camille » : une personne inscrite deux fois, ou deux homonymes ? Sans identifiant, impossible de trancher. On vérifie avant de fusionner ou de supprimer une ligne.","cellules":[[0,0],[3,0]]}],"apres":{"titre":"Tableau B : la même liste, mieux structurée","colonnes":["Identifiant","Nom","Prénom","Service","Date inscription"],"lignes":[["AG001","Martin","Camille","RH","2026-03-12"],["AG002","Bernard","Karim","RH","2026-03-12"],["AG003","Petit","Noé","RH","2026-03-13"]],"legende":"Identifiants et données fictifs.","atouts":["chaque information dans sa propre colonne ;","un seul format de date ;","un même libellé de service, issu d'une liste commune ;","un identifiant qui distingue chaque personne ;","des données plus simples à trier, filtrer et comparer."],"avertissement":"**Attention :** le tableau B est une structure cible, pas une correction automatique du tableau A. Il suppose des vérifications faites à la bonne source (même service, doublon confirmé). Sans elles, on n'invente pas de date, on n'attribue pas d'identifiant et on ne fusionne pas deux personnes."}},{"type":"aretenir","texte":"Une donnée bien structurée est plus facile à comprendre, à vérifier et à réutiliser."}]},{"id":"m03-l2","type":"lecon","titre":"Qu'est-ce qu'une donnée de qualité ?","blocs":[{"type":"situation","texte":"Un gestionnaire de scolarité prépare la liste des étudiants inscrits à une formation. Il constate que certaines informations manquent, que d'autres se contredisent, et que plusieurs coordonnées ne semblent plus à jour."},{"type":"activite","ref":"m03-a1"},{"type":"tableau","titre":"Cinq dimensions de la qualité","colonnes":["Dimension","La donnée…","Exemple"],"lignes":[["Exactitude","correspond à la réalité qu'elle représente.","La date de prise de fonction enregistrée est la bonne."],["Complétude","comporte les informations nécessaires à l'usage prévu.","Une inscription dispose de tous les champs indispensables à son traitement."],["Cohérence","ne se contredit pas et respecte les règles définies.","Un même code de formation est utilisé partout de la même façon."],["Actualité","est suffisamment récente pour l'usage attendu.","L'affectation d'un agent a été mise à jour après son changement de service."],["Conformité au format","respecte les conventions nécessaires à son exploitation.","Les dates suivent le format défini dans l'application."]]},{"type":"exemple","etiquette":"Nuance","titre":"Un champ vide n'est pas toujours une erreur","texte":"Certaines informations sont facultatives ou sans objet dans une situation donnée. La complétude se juge toujours **par rapport à l'usage** : une donnée peut suffire pour un besoin et pas pour un autre."},{"type":"activite","ref":"m03-a2"},{"type":"aretenir","texte":"La qualité d'une donnée dépend de sa fiabilité, de sa cohérence et de son adéquation avec l'usage prévu."}]},{"id":"m03-l3","type":"lecon","titre":"Pourquoi utiliser des identifiants et des référentiels ?","blocs":[{"type":"situation","texte":"Sophie reçoit plusieurs listes au sujet de Camille. Elle y trouve :\n\n- Camille Martin ;\n- MARTIN Camille ;\n- C. Martin ;\n- Camille MARTIN.\n\nQuatre personnes, ou une seule ? Impossible de le savoir avec certitude à partir de ces seuls libellés."},{"type":"decision","id":"m03-d1","consigne":"Quatre libellés, peut-être une seule personne. Que fais-tu ?","donnee":"identite","choix":[{"id":"a","texte":"Je fusionne les lignes : c'est sûrement Camille.","implication":"Sans identifiant, tu peux réunir deux personnes différentes, ou effacer une inscription réelle.","trace":"Libellés de Camille fusionnés sans vérification.","etat":"L'identité n'est pas fiable : les lignes ont été réunies trop tôt."},{"id":"b","texte":"Je cherche un identifiant avant de conclure.","implication":"Le nom seul ne suffit pas. L'identifiant, créé une fois, permet de reconnaître Camille dans les autres services.","etat":"On cherche un identifiant avant de dire s'il s'agit de Camille."},{"id":"c","texte":"Je crée une quatrième fiche, une par libellé.","implication":"Camille existerait quatre fois. Chaque service continuerait de travailler sur une personne différente.","trace":"Une fiche de plus pour un libellé déjà vu.","etat":"Plusieurs fiches portent le nom de Camille."}]},{"type":"definition","terme":"Identifiant","texte":"Un code qui distingue de façon fiable chaque enregistrement **au sein d'un système défini** : identifiant étudiant, identifiant agent, numéro d'équipement, identifiant d'exemplaire. Il n'est pas forcément universel : deux applications peuvent attribuer des identifiants différents à la même personne."},{"type":"tableau","titre":"Liste 1 : sans identifiant","colonnes":["Nom","Prénom"],"lignes":[["Martin","Camille"],["Martin","Camille"]],"legende":"Une seule personne inscrite deux fois, ou deux homonymes ? On ne peut pas le savoir."},{"type":"tableau","titre":"Liste 2 : avec identifiant","colonnes":["Identifiant fictif","Nom","Prénom"],"lignes":[["AG104","Martin","Camille"],["AG287","Martin","Camille"]],"legende":"Deux identifiants différents : il s'agit de deux personnes distinctes, qui portent les mêmes nom et prénom."},{"type":"definition","terme":"Référentiel","texte":"Un ensemble organisé de données de référence, utilisé comme point commun pour identifier, décrire ou classer des éléments de façon cohérente : référentiel des structures, des formations, des bâtiments, des types d'équipements…"},{"type":"definition","terme":"Nomenclature","texte":"Un système organisé de catégories, de codes ou de libellés, utilisés selon des règles communes."},{"type":"exemple","titre":"« RH », « DRH » ou « Ressources humaines » ?","texte":"Un service ne devrait pas être désigné indifféremment par l'un ou l'autre de ces termes. Attention : des libellés proches ne sont pas forcément équivalents. C'est le référentiel qui permet de le vérifier."},{"type":"activite","ref":"m03-a3"},{"type":"aretenir","texte":"Les identifiants et les référentiels permettent de parler des mêmes éléments de manière cohérente."}]},{"id":"m03-l4","type":"lecon","titre":"La qualité commence dans les pratiques quotidiennes","blocs":[{"type":"situation","texte":"Tu aides Noé. Le formulaire demande la date de son intervention sur la chaudière du bâtiment C. Tu ne disposes pas de l'information vérifiée. Que fais-tu ?"},{"type":"activite","ref":"m03-a4","carnet":{"donnee":"intervention","effets":{"a":{"trace":"Une date approximative a été saisie pour l'intervention de Noé.","etat":"La date de la chaudière n'est pas vérifiée."},"b":{"trace":"La date d'un autre équipement a été recopiée sur la chaudière.","etat":"La date ne correspond pas à cet équipement."},"c":{"etat":"La date manque, et c'est signalé. Elle n'a pas été inventée."}}}},{"type":"texte","titre":"Des gestes simples","texte":"La qualité des données repose sur des pratiques simples :\n\n- vérifier une information lorsqu'un doute existe ;\n- utiliser les formats prévus ;\n- respecter les nomenclatures applicables ;\n- ne pas inventer une valeur pour remplir un champ ;\n- signaler une anomalie ;\n- utiliser les sources appropriées ;\n- corriger une information selon les procédures autorisées."},{"type":"exemple","etiquette":"Bon à savoir","titre":"Tu n'as pas à tout corriger seul","texte":"Repérer une erreur ne veut pas dire la corriger soi-même. Selon ta mission et tes droits dans l'application, le bon geste peut être de la signaler au service compétent, qui saura vérifier et corriger à la source."},{"type":"aretenir","texte":"Je contribue à la qualité des données en saisissant, vérifiant et signalant les informations avec rigueur."}]},{"id":"m03-defi","type":"evaluation","titre":"Le défi du module","surtitre":"Défi final","libelleAcces":"Relever le défi","libelleRecommencer":"Recommencer le défi","presentation":"une-par-une","introduction":"Quatre situations, une question à la fois. Tu découvres la correction après chaque réponse, et tu peux recommencer le défi autant de fois que tu le souhaites.","activites":["m03-q1","m03-q2","m03-q3","m03-q4"],"messagesResultat":[{"min":100,"texte":"Bravo ! Tu sais reconnaître ce qui rend une donnée fiable, structurée et réutilisable."},{"min":75,"texte":"Très bien. Relis la correction de la question à revoir : elle reprend une notion clé du module."},{"min":50,"texte":"C'est un bon début. Les corrections et les points à retenir t'aideront à consolider les notions de structure, d'identifiant et de référentiel."},{"min":0,"texte":"Ces notions sont nouvelles pour beaucoup de personnes. Prends le temps de relire les corrections, puis recommence le défi quand tu le souhaites."}]}],"activites":{"m03-a1":{"type":"vrai-faux","objectif":"os3-1","notation":{"formative":true,"points":1},"consigne":"Vrai ou faux : toutes les données enregistrées dans un logiciel sont nécessairement fiables.","reponse":false,"explication":{"correct":"C'est bien faux. Un logiciel peut contenir des informations incomplètes, obsolètes ou incorrectes : il conserve ce qu'on y a saisi, sans pouvoir toujours le vérifier. D'où l'intérêt de connaître les dimensions de la qualité.","incorrect":"En réalité, c'est faux. Un logiciel peut contenir des informations incomplètes, obsolètes ou incorrectes : il conserve ce qu'on y a saisi, sans pouvoir toujours le vérifier."}},"m03-a2":{"type":"classement","objectif":"os3-1","notation":{"formative":true,"points":1},"consigne":"Pour chaque situation, choisis la dimension de qualité principalement concernée.","categories":[{"id":"e","texte":"Exactitude"},{"id":"c","texte":"Complétude"},{"id":"h","texte":"Cohérence"},{"id":"a","texte":"Actualité"},{"id":"f","texte":"Conformité au format"}],"elements":[{"id":"1","texte":"Scolarité : deux codes différents sont utilisés pour la même formation.","categorie":"h","explication":"Les données se contredisent : c'est un problème de cohérence."},{"id":"2","texte":"Maintenance : la date de contrôle enregistrée ne correspond pas à la date réelle du contrôle.","categorie":"e","explication":"La donnée ne correspond pas à la réalité : c'est un problème d'exactitude."},{"id":"3","texte":"RH : l'ancienne affectation d'un agent est toujours affichée.","categorie":"a","explication":"L'information était juste, mais elle n'a pas été mise à jour : c'est un problème d'actualité."},{"id":"4","texte":"Finances : les dates d'un tableau de suivi sont saisies dans plusieurs formats, différents du format attendu.","categorie":"f","explication":"Les conventions de saisie ne sont pas respectées : c'est un problème de conformité au format."},{"id":"5","texte":"Inscription : un champ obligatoire du dossier n'est pas renseigné.","categorie":"c","explication":"Une information indispensable manque : c'est un problème de complétude."}],"explication":{"correct":"Bravo, tes associations sont justes. Dans la réalité, une même situation peut toucher plusieurs dimensions à la fois : des formats de date différents posent aussi un problème de cohérence, par exemple.","incorrect":"Certaines associations sont à revoir : les explications ci-dessus précisent la dimension principalement concernée. Pas d'inquiétude : une même situation peut souvent toucher plusieurs dimensions à la fois."}},"m03-a3":{"type":"choix-unique","objectif":"os3-3","notation":{"formative":true,"points":1},"consigne":"Deux fichiers utilisent des noms différents pour désigner une structure. Quel est le meilleur réflexe ?","choix":[{"id":"a","texte":"Choisir le libellé le plus court.","feedback":"Un libellé court est pratique, mais rien ne garantit qu'il désigne la bonne structure, ni que les deux libellés renvoient à la même entité."},{"id":"b","texte":"Consulter le référentiel ou la source de référence applicable.","feedback":"Le référentiel permet de vérifier s'il s'agit de la même structure et d'utiliser la désignation commune."},{"id":"c","texte":"Créer un nouveau code local.","feedback":"Un code de plus ajouterait une variante supplémentaire, que les autres services ne connaîtront pas."}],"reponse":"b","explication":{"correct":"Oui. Le référentiel sert justement de point commun : il permet de vérifier si deux libellés désignent la même structure et de les rapprocher sans se tromper.","incorrect":"Le meilleur réflexe est de consulter le référentiel ou la source de référence applicable : il permet de vérifier si deux libellés désignent la même structure, sans le supposer."}},"m03-a4":{"type":"choix-unique","objectif":"os3-6","notation":{"formative":true,"points":1},"consigne":"Une date de contrôle est inconnue, mais le champ de saisie semble obligatoire. Quelle attitude adopter ?","choix":[{"id":"a","texte":"Indiquer une date approximative pour terminer rapidement.","feedback":"Une date approximative serait ensuite lue comme une date réelle, et pourrait fausser le suivi des contrôles."},{"id":"b","texte":"Copier la date de l'équipement voisin.","feedback":"La date d'un autre équipement ne dit rien de celui-ci : ce serait une information inventée."},{"id":"c","texte":"Vérifier la source disponible ou signaler l'information manquante selon la procédure prévue.","feedback":"C'est le bon réflexe : chercher l'information vérifiée, ou signaler qu'elle manque."}],"reponse":"c","explication":{"correct":"Une donnée manquante est préférable à une information inventée qui pourrait ensuite être considérée comme fiable. La conduite concrète dépend de la procédure métier et des possibilités de l'outil.","incorrect":"La bonne attitude est de vérifier la source disponible ou de signaler l'information manquante. Une donnée manquante est préférable à une information inventée qui pourrait ensuite être considérée comme fiable. La conduite concrète dépend de la procédure métier et des possibilités de l'outil."}},"m03-q1":{"type":"choix-unique","objectif":"os3-2","notation":{"formative":false,"points":1},"consigne":"Un fichier contient une colonne unique « Nom Prénom ». Pourquoi peut-elle compliquer le traitement des informations ?","choix":[{"id":"a","texte":"Parce qu'Excel interdit ce type de colonne."},{"id":"b","texte":"Parce qu'il peut être difficile de distinguer automatiquement le nom du prénom."},{"id":"c","texte":"Parce qu'un tableau ne peut contenir que des nombres."}],"reponse":"b","explication":{"correct":"Des champs séparés et clairement définis facilitent les opérations de tri, de recherche et de réutilisation.","incorrect":"La bonne réponse est la deuxième : il devient difficile de distinguer le nom du prénom. Des champs séparés et clairement définis facilitent les opérations de tri, de recherche et de réutilisation."}},"m03-q2":{"type":"choix-unique","objectif":"os3-1","notation":{"formative":false,"points":1},"consigne":"Dans une application de gestion, l'affectation d'un agent n'a pas été mise à jour depuis son changement de service. Quelle dimension de qualité est principalement concernée ?","choix":[{"id":"a","texte":"L'actualité de la donnée."},{"id":"b","texte":"Sa taille informatique."},{"id":"c","texte":"Son apparence graphique."}],"reponse":"a","explication":{"correct":"Une information peut avoir été exacte lors de son enregistrement et devenir obsolète. Sa mise à jour est importante pour les usages qui en dépendent.","incorrect":"La dimension concernée est l'actualité. Une information peut avoir été exacte lors de son enregistrement et devenir obsolète. Sa mise à jour est importante pour les usages qui en dépendent."}},"m03-q3":{"type":"choix-unique","objectif":"os3-4","notation":{"formative":false,"points":1},"consigne":"Deux étudiants portent le même nom et le même prénom. Quelle information permet généralement de les distinguer le plus fiablement dans le système de scolarité ?","choix":[{"id":"a","texte":"Leur ordre d'apparition dans le tableau."},{"id":"b","texte":"Leur prénom écrit en majuscules."},{"id":"c","texte":"Leur identifiant étudiant individuel."}],"reponse":"c","explication":{"correct":"Un identifiant unique dans un périmètre défini permet de distinguer des enregistrements qui présentent des informations similaires.","incorrect":"La bonne réponse est l'identifiant étudiant individuel. Un identifiant unique dans un périmètre défini permet de distinguer des enregistrements qui présentent des informations similaires."}},"m03-q4":{"type":"choix-unique","objectif":"os3-5","notation":{"formative":false,"points":1},"consigne":"Deux services utilisent des libellés différents pour désigner une même catégorie d'équipement. Quelle démarche favorise la cohérence ?","choix":[{"id":"a","texte":"Utiliser un référentiel ou une nomenclature commune adaptée."},{"id":"b","texte":"Conserver des libellés différents sans aucune correspondance."},{"id":"c","texte":"Ajouter autant de variantes que possible."}],"reponse":"a","explication":{"correct":"Des règles de désignation communes facilitent la compréhension, le rapprochement et la réutilisation des données entre services.","incorrect":"La démarche à privilégier est d'utiliser un référentiel ou une nomenclature commune adaptée. Des règles de désignation communes facilitent la compréhension, le rapprochement et la réutilisation des données entre services."}}},"synthese":["Une donnée bien structurée (une information par colonne, des formats homogènes, des libellés communs) est plus facile à comprendre, à vérifier et à réutiliser.","Une donnée de qualité est exacte, complète, cohérente, actualisée et conforme au format attendu, toujours au regard de l'usage prévu.","Les identifiants distinguent les enregistrements dans un système donné ; les référentiels et les nomenclatures permettent de désigner les mêmes éléments de la même façon.","Au quotidien : vérifier en cas de doute, ne pas inventer une valeur, signaler une anomalie et corriger selon les procédures prévues."]},"m04":{"id":"m04","numero":4,"titre":"Partager sans perdre le contrôle","sousTitre":"Comprendre comment utiliser et transmettre des données de manière responsable.","slugArchive":"partager-sans-perdre-controle","duree":10,"statutContenu":"proposition - à valider (notamment par le DPO)","objectif":"Comprendre que le partage des données peut être nécessaire au fonctionnement collectif de l'université, mais qu'il doit respecter des règles adaptées à leur nature, aux finalités de leur utilisation et aux personnes autorisées.","objectifsSpecifiques":[{"id":"os4-1","texte":"Distinguer une donnée personnelle d'une donnée qui ne l'est pas."},{"id":"os4-2","texte":"Reconnaître que certaines données nécessitent une protection particulière."},{"id":"os4-3","texte":"Comprendre les notions de finalité et d'habilitation."},{"id":"os4-4","texte":"Identifier les principaux risques d'un partage non maîtrisé."},{"id":"os4-5","texte":"Reconnaître les situations nécessitant une vérification avant transmission."},{"id":"os4-6","texte":"Comprendre que le RGPD encadre le traitement des données personnelles sans en interdire systématiquement le partage."}],"validation":{"navigation":"sequentielle","leconsObligatoires":true,"evaluation":"m04-defi"},"lecons":[{"id":"m04-l1","type":"lecon","titre":"Toutes les données ne se partagent pas de la même manière","blocs":[{"type":"situation","texte":"Trois demandes arrivent en même temps :\n\n- Noé veut le numéro d'une salle pour une intervention ;\n- Sophie veut la liste des agents du service, avec leurs coordonnées professionnelles ;\n- un collègue veut le tableau des rémunérations individuelles, tenu par Julie.\n\nCes informations n'ont pas la même nature : elles ne demandent pas les mêmes précautions."},{"type":"definition","terme":"Donnée personnelle","texte":"Une information qui se rapporte à une personne physique **identifiée ou identifiable**, directement ou non : nom et prénom, adresse électronique nominative (même professionnelle), numéro étudiant, identifiant agent, adresse personnelle, certaines données de connexion, rémunération individuelle… Elle n'a pas besoin d'être secrète pour être personnelle."},{"type":"definition","terme":"Donnée non personnelle","texte":"Une information qui ne permet d'identifier personne : nombre de salles d'un bâtiment, référence d'un équipement, nombre de documents d'une bibliothèque."},{"type":"exemple","etiquette":"Attention","titre":"Une donnée anodine peut devenir personnelle","texte":"Croisée avec d'autres informations, elle peut permettre d'identifier quelqu'un : « un agent de 58 ans, dans un service de trois personnes » ne cite aucun nom, et pourtant on devine souvent de qui il s'agit."},{"type":"tableau","titre":"Trois notions à ne pas confondre","colonnes":["Notion","Ce que cela veut dire","Exemple"],"lignes":[["Donnée personnelle","Se rapporte à une personne identifiée ou identifiable.","Adresse électronique nominative"],["Donnée confidentielle","Ne doit être connue que des personnes autorisées, qu'elle soit personnelle ou non.","Rémunération individuelle, dossier administratif d'un agent, mot de passe"],["Catégorie particulière (article 9 du RGPD)","Liste précise de données à protection renforcée : santé, origine, opinions politiques, convictions religieuses, appartenance syndicale, données génétiques ou biométriques, vie ou orientation sexuelle.","Information médicale"]],"legende":"Une rémunération individuelle demande une grande confidentialité, sans être pour autant une catégorie particulière au sens de l'article 9."},{"type":"activite","ref":"m04-a1"},{"type":"aretenir","texte":"Toutes les données ne présentent pas les mêmes enjeux de protection."}]},{"id":"m04-l2","type":"lecon","titre":"Pourquoi partage-t-on une donnée ?","blocs":[{"type":"situation","texte":"Le service de scolarité reçoit, d'un autre service de l'université, une demande de liste nominative d'étudiants.\n\nFaut-il envoyer le fichier tout de suite ? Pas forcément : il faut d'abord comprendre **pourquoi** ces informations sont demandées."},{"type":"definition","terme":"Finalité","texte":"L'objectif déterminé pour lequel des données personnelles sont utilisées. Un service qui gère les inscriptions pédagogiques a besoin de certaines données d'inscription pour cette mission ; cela ne lui permet pas de les réutiliser automatiquement pour n'importe quel autre objectif."},{"type":"definition","terme":"Minimisation","texte":"Limiter les données personnelles à ce qui est **adéquat, pertinent et nécessaire** au regard de la finalité."},{"type":"tableau","titre":"Un besoin, quelles données ?","colonnes":["Besoin","Ce qui suffit","Inutile pour ce besoin"],"lignes":[["Préparer une salle pour une formation","Le nombre d'étudiants inscrits","Noms, dates de naissance, adresses personnelles"],["Envoyer une convocation à un examen","Nom, prénom, adresse électronique, formation suivie","Situation familiale, coordonnées bancaires"]],"legende":"Exemples illustratifs : le besoin réel s'apprécie au cas par cas."},{"type":"activite","ref":"m04-a2"},{"type":"aretenir","texte":"Avant de partager une donnée personnelle, je cherche à comprendre la finalité et quelles informations sont réellement nécessaires."}]},{"id":"m04-l3","type":"lecon","titre":"Qui a le droit d'accéder aux données ?","blocs":[{"type":"situation","texte":"Tu travailles dans un service RH. Un collègue d'un autre service te demande des informations détaillées sur la situation administrative d'un agent.\n\nIl travaille dans la même université : est-ce suffisant pour lui répondre ? **Non.** Travailler dans le même établissement ne donne pas accès à toutes les informations."},{"type":"definition","terme":"Habilitation","texte":"Une autorisation d'accès attribuée à une personne ou à une fonction, dans un cadre défini et en cohérence avec ses missions. Elle organise qui peut consulter ou traiter certaines données."},{"type":"schema","titre":"Avant de transmettre : trois critères à examiner ensemble","source":{"libelle":"Une demande de données","detail":"« Tu peux m'envoyer… ? »"},"flux":"s'examine selon","annonce":"Trois critères à examiner :","consigne":"Sélectionne un critère pour découvrir la question à se poser.","cibles":[{"libelle":"Finalité déterminée","usage":"Pourquoi cette demande ?","detail":"La personne doit pouvoir expliquer l'objectif poursuivi, en lien avec ses missions. « J'en ai besoin » ne suffit pas : pour quoi faire ?"},{"libelle":"Données nécessaires","usage":"Faut-il toutes ces informations ?","detail":"On ne transmet que ce qui est utile à l'objectif. Souvent, un extrait, un total ou des données non nominatives suffisent."},{"libelle":"Accès autorisé","usage":"Cette personne peut-elle les recevoir ?","detail":"Ses fonctions lui donnent-elles le droit d'accéder à ces données, ou une procédure permet-elle de le vérifier ? Avoir techniquement accès à une application ne justifie pas, à lui seul, n'importe quel usage des données."}],"legende":"Ces trois critères ne suffisent pas toujours : le traitement doit aussi reposer sur une base légale et respecter les autres règles applicables."},{"type":"activite","ref":"m04-a3"},{"type":"aretenir","texte":"Travailler dans la même organisation ne signifie pas avoir accès aux mêmes données."}]},{"id":"m04-l4","type":"lecon","titre":"Le RGPD interdit-il de partager les données ?","blocs":[{"type":"situation","texte":"Un agent doit répondre à la demande d'un autre service. Il hésite : « Je préfère refuser : avec le RGPD, on ne peut plus transmettre de données personnelles. »\n\n**Cette affirmation est incorrecte.**"},{"type":"texte","titre":"Un cadre, pas une interdiction","texte":"Le RGPD n'interdit pas systématiquement de transmettre des données personnelles. Il fixe un cadre, qui prévoit notamment :\n\n- une base juridique appropriée ;\n- une finalité déterminée et légitime ;\n- la minimisation des données ;\n- la sécurité et la confidentialité ;\n- la transparence envers les personnes concernées ;\n- le respect de leurs droits ;\n- une durée de conservation adaptée.\n\nUn partage peut donc être possible s'il respecte ces conditions. Mais un besoin professionnel ne suffit pas, à lui seul, à le rendre légal : les règles de l'établissement et les responsabilités définies s'appliquent aussi."},{"type":"memo","titre":"Les quatre réflexes avant de transmettre","etapes":[{"titre":"Comprendre","texte":"Quel est l'objectif de la demande ?"},{"titre":"Vérifier","texte":"Quelles données sont nécessaires, et qui est autorisé à les recevoir ?"},{"titre":"Sécuriser","texte":"Quel canal de transmission ou mode d'accès est prévu et approprié ?"},{"titre":"Demander conseil","texte":"En cas de doute : ton responsable, le référent métier, le DPO ou le service compétent, selon la procédure interne."}],"legende":"Tu n'as pas à mener seul une analyse juridique complexe : demander conseil fait partie du bon réflexe."},{"type":"activite","ref":"m04-a4"},{"type":"simulateur","titre":"Puis-je partager cette donnée ?","consigne":"Quatre demandes fictives. Pour chacune, choisis la conduite à tenir, puis découvre la correction.","avertissement":"Exercice de sensibilisation, pas un outil de validation : face à une demande réelle, suis les procédures de l'établissement et demande conseil aux personnes compétentes.","decisions":[{"id":"partager","libelle":"Partager","icone":"↗"},{"id":"verifier","libelle":"Vérifier avant de décider","icone":"🔍"},{"id":"ne-pas-transmettre","libelle":"Ne pas transmettre en l'état","icone":"✋"}],"scenarios":[{"id":"salles","objectif":"os4-3","titre":"Préparer une salle","contexte":"Le service logistique doit réserver une salle pour une formation.","demandeur":"Service logistique","finalite":"Prévoir une salle de capacité suffisante","donnees":"Le nombre de participants inscrits","choix":[{"id":"a","decision":"partager","texte":"Transmettre l'effectif global des inscrits.","feedback":"Un chiffre répond entièrement au besoin, sans faire circuler de données nominatives."},{"id":"b","decision":"verifier","texte":"Demander l'avis du DPO avant de donner le chiffre.","feedback":"Prudent, mais pas nécessaire ici : un effectif global ne permet pas, en général, d'identifier les participants. Le DPO est à solliciter en cas de doute réel."},{"id":"c","decision":"ne-pas-transmettre","texte":"Refuser : la liste des inscrits contient des données personnelles.","feedback":"Le besoin porte sur un nombre, pas sur la liste. Refuser bloquerait l'organisation sans protéger personne davantage."}],"carnet":{"donnee":"salle","effets":{"a":{"etat":"L'effectif a été transmis pour la salle. Les noms ne circulent pas."},"b":{"etat":"La demande de salle est en attente. Rien n'a encore été transmis."},"c":{"etat":"Rien n'a été transmis. La préparation de la salle est bloquée."}}},"reponse":"a","correction":{"pourquoi":"Le besoin est légitime et un chiffre suffit : c'est la minimisation.","aVerifier":["Le besoin porte-t-il bien sur un nombre, et non sur des noms ?","Le groupe est-il assez grand pour que le chiffre n'identifie personne ?"],"risque":"Envoyer la liste complète par habitude, ou bloquer un besoin simple.","reflexe":"Quand un effectif suffit, je transmets un effectif."}},{"id":"remunerations","objectif":"os4-4","titre":"Un fichier de rémunérations","contexte":"Un collègue t'écrit : « Tu peux m'envoyer le fichier des rémunérations de l'équipe ? » Il ne dit pas pourquoi.","demandeur":"Un collègue d'un autre service","finalite":"Non précisée","donnees":"Les rémunérations individuelles des agents, nominatives","choix":[{"id":"a","decision":"partager","texte":"Envoyer le fichier : c'est un collègue de l'université.","feedback":"Être collègue ne donne pas accès aux rémunérations individuelles. Le fichier pourrait arriver chez une personne qui n'a pas à les connaître."},{"id":"b","decision":"verifier","texte":"Lui demander l'objectif de sa demande, et vérifier avec ton responsable s'il peut accéder à ces données.","feedback":"C'est le bon réflexe : tant que la finalité et le droit d'accès ne sont pas vérifiés, on ne transmet pas."},{"id":"c","decision":"ne-pas-transmettre","texte":"Refuser définitivement, sans autre échange.","feedback":"Ne pas envoyer tout de suite est juste. Mais refuser sans chercher à comprendre peut bloquer une mission légitime : mieux vaut clarifier la demande."}],"carnet":{"donnee":"remunerations","effets":{"a":{"trace":"Le fichier des rémunérations a été envoyé sans besoin précisé.","etat":"Les rémunérations ont quitté le service de Julie."},"b":{"etat":"Les rémunérations restent chez Julie. La demande est à clarifier."},"c":{"etat":"Les rémunérations restent chez Julie."}}},"reponse":"b","correction":{"pourquoi":"Données personnelles très confidentielles, finalité inconnue, accès non vérifié : on ne peut pas encore décider.","aVerifier":["L'objectif de la demande, et si des données agrégées suffiraient.","L'habilitation du demandeur et la procédure applicable."],"risque":"Divulguer des rémunérations individuelles à une personne non autorisée.","reflexe":"Demande floue sur des données confidentielles : je clarifie et je vérifie avant de transmettre."}},{"id":"bibliotheque","objectif":"os4-5","titre":"Un inventaire de la bibliothèque","contexte":"Le service chargé de l'inventaire des collections demande à la bibliothèque une liste de références bibliographiques.","demandeur":"Le service chargé de l'inventaire","finalite":"Constituer un inventaire des collections","donnees":"Des références bibliographiques (titre, auteur, cote…)","complement":"Certaines notices viennent de fournisseurs extérieurs. L'export disponible contient aussi l'historique des prêts.","choix":[{"id":"a","decision":"partager","texte":"Envoyer immédiatement l'export complet du catalogue.","feedback":"L'export contient l'historique des prêts, qui renvoie à des lecteurs. Et les conditions de réutilisation des notices n'ont pas été vérifiées."},{"id":"b","decision":"verifier","texte":"Vérifier les conditions de réutilisation, puis transmettre seulement les références utiles à l'inventaire.","feedback":"C'est le bon réflexe : le partage est sans doute possible, après ces vérifications et sans les données de prêt."},{"id":"c","decision":"ne-pas-transmettre","texte":"Refuser : les données de la bibliothèque ne se partagent pas.","feedback":"Des références bibliographiques ne sont en général pas des données personnelles, et l'inventaire est une mission légitime. Refuser par principe bloquerait un travail utile."}],"carnet":{"donnee":"catalogue-biblio","effets":{"a":{"trace":"L'export complet du catalogue, historique des prêts compris, a été envoyé.","etat":"Des données de lecteurs ont quitté la bibliothèque."},"b":{"etat":"Seules les références utiles peuvent partir. L'historique des prêts reste chez Karim."},"c":{"etat":"Le catalogue reste à la bibliothèque."}}},"reponse":"b","correction":{"pourquoi":"Des références bibliographiques ne sont en général pas des données personnelles. Mais leur réutilisation peut être encadrée par des licences, et l'export contient d'autres informations.","aVerifier":["Les licences ou accords qui encadrent les notices.","Le contenu de l'export : rien sur les lecteurs ni sur les prêts."],"risque":"Transmettre sans le voir des données sur les lecteurs, ou bloquer un inventaire légitime.","reflexe":"Même sans données personnelles, je vérifie ce que je transmets et à quelles conditions."}},{"id":"sante","objectif":"os4-2","titre":"Des informations médicales","contexte":"Pour une journée d'intégration, un responsable te demande les informations médicales des étudiants concernés, « pour prévoir les aménagements ».","demandeur":"Un responsable de formation","finalite":"Prévoir d'éventuels aménagements","donnees":"Des informations médicales individuelles d'étudiants","choix":[{"id":"a","decision":"partager","texte":"Envoyer les informations médicales des étudiants concernés.","feedback":"Des données de santé parviendraient à une personne qui n'a pas à les connaître : un risque sérieux pour les étudiants."},{"id":"b","decision":"verifier","texte":"Lui demander de justifier son besoin, puis lui envoyer les informations médicales s'il le justifie.","feedback":"Une justification ne change rien ici : un organisateur n'a pas à connaître des détails médicaux pour prévoir un aménagement."},{"id":"c","decision":"ne-pas-transmettre","texte":"Ne pas transmettre ces informations, et orienter la demande vers les services compétents.","feedback":"C'est le bon réflexe : les services compétents indiqueront comment prévoir les aménagements, sans communiquer de détails médicaux."}],"carnet":{"donnee":"sante","effets":{"a":{"trace":"Des informations de santé ont été transmises à l'organisateur.","etat":"Des données de santé ont quitté leur service."},"b":{"etat":"La demande est encore ouverte. Le détail médical ne doit pas partir."},"c":{"etat":"Les informations de santé ne circulent pas. La demande est orientée."}}},"reponse":"c","correction":{"pourquoi":"Les données de santé sont une catégorie particulière du RGPD. L'organisateur a besoin de savoir quoi prévoir, pas de connaître l'état de santé des personnes.","aVerifier":["Le service compétent dans l'établissement (santé, accompagnement du handicap…).","Les informations pratiques, non médicales, utiles à l'organisateur."],"risque":"Exposer des informations de santé, au détriment des étudiants.","reflexe":"Données de santé : je ne transmets pas, j'oriente vers les personnes compétentes."}}],"conclusion":"Ni tout partager, ni tout bloquer : je comprends le besoin, je vérifie les autorisations et les règles applicables, puis je décide, ou je demande conseil."},{"type":"aretenir","texte":"Le RGPD organise un usage responsable des données personnelles : il ne signifie pas que tout partage est interdit."}]},{"id":"m04-defi","type":"evaluation","titre":"Le défi du module","surtitre":"Défi final","libelleAcces":"Relever le défi","libelleRecommencer":"Recommencer le défi","presentation":"une-par-une","introduction":"Quatre situations, une question à la fois. Tu découvres la correction après chaque réponse, et tu peux recommencer le défi autant de fois que tu le souhaites.","activites":["m04-q1","m04-q2","m04-q3","m04-q4"],"messagesResultat":[{"min":100,"texte":"Bravo ! Tu sais qu'il ne faut ni tout partager ni tout bloquer, mais vérifier le besoin, les autorisations et les règles applicables."},{"min":75,"texte":"Très bien. Relis la correction de la question à revoir : elle reprend un réflexe clé du partage responsable."},{"min":50,"texte":"C'est un bon début. Les corrections t'aideront à consolider les notions de donnée personnelle, de finalité et d'habilitation."},{"min":0,"texte":"Ces notions sont nouvelles pour beaucoup de personnes. Prends le temps de relire les corrections, puis recommence le défi quand tu le souhaites."}]}],"activites":{"m04-a1":{"type":"classement","objectif":"os4-1","notation":{"formative":true,"points":1},"consigne":"Pour chaque information, choisis la catégorie qui convient dans le contexte présenté.","categories":[{"id":"n","texte":"Donnée non personnelle (dans ce contexte)"},{"id":"p","texte":"Donnée personnelle"},{"id":"s","texte":"Catégorie particulière du RGPD"}],"elements":[{"id":"1","texte":"L'adresse électronique nominative d'un agent.","categorie":"p","explication":"Elle identifie directement une personne, même si elle est professionnelle."},{"id":"2","texte":"Le nombre de places disponibles dans un amphithéâtre.","categorie":"n","explication":"Ce chiffre décrit une salle, pas une personne."},{"id":"3","texte":"La rémunération individuelle d'un agent.","categorie":"p","explication":"C'est une donnée personnelle très confidentielle, mais elle ne relève pas, à elle seule, des catégories particulières du RGPD."},{"id":"4","texte":"Une information médicale concernant un étudiant.","categorie":"s","explication":"Les données de santé font partie des catégories particulières du RGPD : elles bénéficient d'une protection renforcée."}],"explication":{"correct":"Bravo. Attention : le classement dépend parfois du contexte. Un chiffre portant sur un très petit groupe, croisé avec d'autres informations, peut permettre d'identifier une personne.","incorrect":"Certaines réponses sont à revoir : les explications ci-dessus précisent la catégorie attendue. Le classement dépend parfois du contexte et des possibilités d'identification."}},"m04-a2":{"type":"choix-unique","objectif":"os4-3","notation":{"formative":true,"points":1},"consigne":"Le service logistique souhaite connaître le nombre d'étudiants inscrits à une conférence, pour déterminer la capacité nécessaire. Que faire ?","choix":[{"id":"a","texte":"Transmettre le fichier complet des étudiants avec leurs coordonnées.","feedback":"Le fichier complet contient bien plus que ce qui est utile pour dimensionner une salle : ces données n'ont pas à circuler pour ce besoin."},{"id":"b","texte":"Transmettre uniquement le nombre d'inscrits, si cette information suffit au besoin.","feedback":"C'est le bon réflexe : un chiffre suffit pour prévoir la capacité."},{"id":"c","texte":"Refuser toute transmission, car les inscriptions concernent des étudiants.","feedback":"Refuser bloquerait un besoin légitime, alors qu'un effectif ne permet pas, en général, d'identifier les étudiants."}],"reponse":"b","explication":{"correct":"Lorsqu'une information agrégée suffit à répondre au besoin, il n'est pas nécessaire de transmettre des données nominatives.","incorrect":"La bonne réponse est la deuxième. Lorsqu'une information agrégée suffit à répondre au besoin, il n'est pas nécessaire de transmettre des données nominatives."}},"m04-a3":{"type":"choix-unique","objectif":"os4-5","notation":{"formative":true,"points":1},"consigne":"Une personne demande une extraction RH nominative, sans préciser son objectif. Que faut-il faire ?","choix":[{"id":"a","texte":"Transmettre le fichier, puisqu'il s'agit d'un collègue.","feedback":"Être collègue ne suffit pas : l'accès dépend des missions et des autorisations, pas de l'appartenance à l'établissement."},{"id":"b","texte":"Vérifier la finalité, les droits et la procédure applicable avant toute transmission.","feedback":"C'est le bon réflexe : vérifier avant de transmettre."},{"id":"c","texte":"Publier les données sur un espace partagé accessible à toute l'université.","feedback":"Des données RH nominatives seraient alors exposées à des personnes qui n'ont pas à les connaître."}],"reponse":"b","explication":{"correct":"Une demande professionnelle doit être examinée selon le besoin, l'autorisation d'accès et les règles applicables. En cas de doute, il faut solliciter les personnes compétentes.","incorrect":"La bonne réponse est la deuxième. Une demande professionnelle doit être examinée selon le besoin, l'autorisation d'accès et les règles applicables. En cas de doute, il faut solliciter les personnes compétentes."}},"m04-a4":{"type":"choix-unique","objectif":"os4-6","notation":{"formative":true,"points":1},"consigne":"Un service habilité demande certaines données nécessaires à une mission identifiée. Une procédure interne prévoit leur transmission sécurisée. Que faire ?","choix":[{"id":"a","texte":"Refuser automatiquement, car ce sont des données personnelles.","feedback":"Refuser par principe bloquerait une mission identifiée, alors qu'une procédure encadre déjà cette transmission."},{"id":"b","texte":"Suivre la procédure autorisée, après les vérifications prévues.","feedback":"C'est le bon réflexe : le cadre existe, il suffit de le suivre."},{"id":"c","texte":"Envoyer le fichier à l'ensemble du personnel pour assurer la transparence.","feedback":"La transparence ne consiste pas à diffuser des données personnelles à tous : ce serait un partage non maîtrisé."}],"reponse":"b","explication":{"correct":"Le RGPD permet des traitements et transmissions de données personnelles lorsqu'ils reposent sur un cadre juridique approprié et respectent les règles applicables.","incorrect":"La bonne réponse est la deuxième. Le RGPD permet des traitements et transmissions de données personnelles lorsqu'ils reposent sur un cadre juridique approprié et respectent les règles applicables."}},"m04-q1":{"type":"choix-unique","objectif":"os4-1","notation":{"formative":false,"points":1},"consigne":"Une adresse électronique professionnelle nominative constitue-t-elle une donnée personnelle ?","choix":[{"id":"a","texte":"Non, puisqu'elle appartient à une organisation."},{"id":"b","texte":"Oui, lorsqu'elle permet d'identifier une personne physique."},{"id":"c","texte":"Seulement si elle figure dans un document confidentiel."}],"reponse":"b","explication":{"correct":"Une donnée professionnelle peut être une donnée personnelle lorsqu'elle identifie directement ou indirectement une personne.","incorrect":"La bonne réponse est la deuxième. Une donnée professionnelle peut être une donnée personnelle lorsqu'elle identifie directement ou indirectement une personne."}},"m04-q2":{"type":"choix-unique","objectif":"os4-3","notation":{"formative":false,"points":1},"consigne":"Le service logistique souhaite connaître le nombre d'étudiants inscrits à une conférence. Quelle information est généralement suffisante ?","choix":[{"id":"a","texte":"Un effectif global."},{"id":"b","texte":"La liste complète avec adresses personnelles."},{"id":"c","texte":"L'intégralité des dossiers d'inscription."}],"reponse":"a","explication":{"correct":"Il faut limiter les données personnelles utilisées aux informations nécessaires à l'objectif poursuivi.","incorrect":"La bonne réponse est l'effectif global. Il faut limiter les données personnelles utilisées aux informations nécessaires à l'objectif poursuivi."}},"m04-q3":{"type":"choix-unique","objectif":"os4-3","notation":{"formative":false,"points":1},"consigne":"Un collègue demande une extraction RH détaillée sans préciser le motif. Quelle attitude adopter ?","choix":[{"id":"a","texte":"Transmettre, puisqu'il travaille dans l'université."},{"id":"b","texte":"Vérifier la finalité et les autorisations avant transmission."},{"id":"c","texte":"Envoyer le fichier sans contrôle, puis demander une justification après."}],"reponse":"b","explication":{"correct":"Le partage doit respecter les missions, les droits d'accès et les règles applicables.","incorrect":"La bonne réponse est la deuxième : vérifier la finalité et les autorisations avant transmission. Le partage doit respecter les missions, les droits d'accès et les règles applicables."}},"m04-q4":{"type":"choix-unique","objectif":"os4-6","notation":{"formative":false,"points":1},"consigne":"Quelle affirmation est correcte ?","choix":[{"id":"a","texte":"Le RGPD interdit tout partage de données personnelles."},{"id":"b","texte":"Une donnée personnelle peut toujours être transmise entre collègues."},{"id":"c","texte":"Le RGPD encadre les conditions dans lesquelles des données personnelles peuvent être traitées et partagées."}],"reponse":"c","explication":{"correct":"Le RGPD définit un cadre de protection et de traitement responsable. Le partage peut être possible lorsqu'il respecte les conditions applicables.","incorrect":"La bonne réponse est la troisième. Le RGPD définit un cadre de protection et de traitement responsable. Le partage peut être possible lorsqu'il respecte les conditions applicables."}}},"synthese":["Une donnée personnelle peut aussi être une donnée professionnelle.","Toutes les données n'exigent pas les mêmes précautions.","Le partage doit répondre à une finalité et respecter les règles applicables.","Les informations transmises doivent être limitées au besoin.","Les droits d'accès et les habilitations doivent être vérifiés.","En cas de doute, il faut se rapprocher des personnes compétentes.","Le RGPD n'interdit pas systématiquement le partage."]},"m05":{"id":"m05","numero":5,"titre":"Qui organise les données ?","sousTitre":"Comprendre la gouvernance, la gestion des données et les responsabilités de chacun.","slugArchive":"qui-organise-les-donnees","duree":8,"statutContenu":"proposition - à valider (rôles à confirmer avec les équipes chargées de la gouvernance de la donnée)","objectif":"Comprendre que la gouvernance de la donnée repose sur des règles, des décisions, une organisation et des responsabilités partagées, et la distinguer de la gestion des données au quotidien.","objectifsSpecifiques":[{"id":"os5-1","texte":"Expliquer simplement ce qu'est la gouvernance de la donnée."},{"id":"os5-2","texte":"Distinguer gouvernance et gestion opérationnelle des données."},{"id":"os5-3","texte":"Reconnaître les principales catégories d'acteurs intervenant dans la gestion des données."},{"id":"os5-4","texte":"Comprendre pourquoi les responsabilités doivent être identifiées."},{"id":"os5-5","texte":"Reconnaître le rôle des services métiers, de l'encadrement et des services techniques."},{"id":"os5-6","texte":"Comprendre que chacun contribue à la qualité et à l'utilisation responsable des données."}],"validation":{"navigation":"sequentielle","leconsObligatoires":true,"evaluation":"m05-defi"},"lecons":[{"id":"m05-l1","type":"lecon","titre":"Pourquoi faut-il des règles communes ?","blocs":[{"type":"situation","texte":"Le service RH gère les informations sur les personnels, la scolarité celles sur les étudiants et les formations, le patrimoine celles sur les bâtiments et les équipements. Chacun utilise des outils et des procédures adaptés à ses missions, et c'est légitime.\n\nMais certaines informations doivent aussi être comprises ou réutilisées par d'autres services."},{"type":"exemple","titre":"« Département Sciences », « Dept. Sciences » ou « DS » ?","texte":"Trois fichiers désignent une structure de ces trois façons. S'agit-il de la même structure ? Pas forcément. Sans règle ni référentiel commun, il est difficile de rapprocher les informations."},{"type":"texte","titre":"Ce que fait la gouvernance","texte":"La gouvernance définit un **cadre partagé** : objectifs, règles communes, responsabilités, modalités de décision, principes de qualité, conditions de partage, façons de faire évoluer les règles.\n\nElle n'impose pas à tous les services les mêmes outils ou les mêmes procédures : elle cherche une cohérence adaptée aux besoins collectifs."},{"type":"activite","ref":"m05-a1"},{"type":"aretenir","texte":"La gouvernance permet de définir des règles communes pour mieux travailler ensemble."}]},{"id":"m05-l2","type":"lecon","titre":"Gouvernance et gestion des données : quelle différence ?","blocs":[{"type":"situation","texte":"L'université veut des informations plus fiables sur ses bâtiments. Deux types d'actions sont nécessaires :\n\n- décider qui valide les informations, quelles règles respecter et comment traiter les incohérences ;\n- mettre à jour l'application, contrôler les enregistrements et signaler les anomalies.\n\nCes actions sont complémentaires, mais elles ne se situent pas au même niveau."},{"type":"definition","terme":"Gouvernance de la donnée","texte":"L'organisation des décisions, des règles, des responsabilités et du contrôle concernant les données. Elle répond à : pourquoi gérons-nous ces données ? Quelles règles communes ? Qui décide ? Qui est responsable de quoi ? Comment arbitrer ?"},{"type":"definition","terme":"Gestion opérationnelle","texte":"Les activités concrètes qui permettent de créer, saisir, contrôler, mettre à jour, utiliser, partager, archiver ou supprimer les données, **selon les règles applicables**."},{"type":"tableau","titre":"Deux niveaux complémentaires","colonnes":["Gouvernance","Gestion opérationnelle"],"lignes":[["Définir une règle de qualité","Appliquer cette règle lors de la saisie"],["Attribuer des responsabilités","Effectuer les contrôles prévus"],["Définir les principes d'accès","Accorder les accès selon la procédure"],["Fixer les principes d'actualisation","Mettre à jour les informations"],["Organiser les arbitrages","Signaler et traiter les anomalies"]],"legende":"Distinction simplifiée : dans la réalité, responsables métiers et équipes opérationnelles contribuent souvent aux deux."},{"type":"activite","ref":"m05-a2"},{"type":"aretenir","texte":"La gouvernance organise les règles et les responsabilités ; la gestion opérationnelle les traduit en actions concrètes."}]},{"id":"m05-l3","type":"lecon","titre":"Qui intervient dans la gouvernance des données ?","blocs":[{"type":"situation","texte":"L'affectation de Camille n'est pas la même chez Julie et dans le fichier de Sophie. Noé, de son côté, a peut-être une autre date pour la salle.\n\nUn agent constate l'écart. Quelqu'un doit décider comment le traiter. Un référent aide à comprendre la donnée. Une équipe technique intervient si l'application est en cause.\n\nQui agit ? Cela dépend des rôles et des procédures définis."},{"type":"decision","id":"m05-d1","consigne":"L'affectation de Camille diverge. Que fais-tu ?","donnee":"arrivee-camille","choix":[{"id":"a","texte":"Je corrige le fichier de Sophie moi-même, sans prévenir Julie.","implication":"Le bureau semble juste. Le dossier de Julie, qui fait référence, porte encore l'erreur. Elle reviendra au prochain envoi.","trace":"Fichier de Sophie corrigé sans revenir au dossier de Julie.","etat":"L'écart est masqué dans une copie. Le dossier de Julie est encore faux."},{"id":"b","texte":"Je signale l'écart à Julie, qui tient le dossier agent.","implication":"Sophie a constaté. Julie peut corriger à la source. Les autres copies pourront ensuite être reprises.","etat":"Sophie a signalé l'écart. La correction appartient au dossier tenu par Julie."},{"id":"c","texte":"Je demande à Noé de modifier la date d'intervention.","implication":"Noé tient les interventions, pas les affectations. La donnée de Camille ne sera pas corrigée au bon endroit.","trace":"La correction a été demandée à Noé, qui ne tient pas le dossier agent.","etat":"La mauvaise personne a été sollicitée. L'affectation de Camille est encore fausse."}]},{"type":"schema","titre":"Cinq familles de rôles qui collaborent","source":{"libelle":"Les données de l'université","detail":"Un bien commun, utile à tous les services"},"flux":"mobilisent des rôles complémentaires","annonce":"Cinq familles de rôles, présentées au même niveau :","consigne":"Sélectionne une famille de rôles pour découvrir sa contribution.","cibles":[{"libelle":"Décider et coordonner","usage":"Décideurs et instances de gouvernance","detail":"Ils définissent ou valident les orientations, les priorités et les règles qui relèvent de leur responsabilité.\n\n- Exemples : fixer des principes communs, arbitrer entre plusieurs besoins, organiser la coordination.\n- Travaillent avec : les responsables métiers, qui expriment les besoins."},{"libelle":"Apporter l'expertise métier","usage":"Responsables métiers","detail":"Ils connaissent les activités et contribuent aux décisions sur les données de leur domaine.\n\n- Exemples : responsable RH, de scolarité, du patrimoine, de bibliothèque.\n- Travaillent avec : les agents de leur service et les décideurs."},{"libelle":"Accompagner la qualité","usage":"Référents ou gestionnaires de données","detail":"Selon l'organisation retenue, ils contribuent à définir, documenter et suivre les règles relatives à certaines données. Leur nom et leur périmètre varient selon les établissements.\n\n- Exemples : documenter une règle de saisie, suivre des indicateurs de qualité.\n- Travaillent avec : les responsables métiers, les agents et les équipes techniques."},{"libelle":"Produire et utiliser","usage":"Agents producteurs et utilisateurs","detail":"Ils manipulent les informations au quotidien : leur expérience du terrain est essentielle.\n\n- Exemples : saisir, contrôler, consulter, mettre à jour, réutiliser, signaler une anomalie.\n- Travaillent avec : leur responsable et les référents, à qui ils font remonter les difficultés."},{"libelle":"Sécuriser et soutenir les usages","usage":"Acteurs techniques et spécialisés","detail":"Ils accompagnent les usages et la sécurisation des données selon leurs compétences.\n\n- Exemples : services informatiques, responsable de la sécurité des systèmes d'information, équipes des applications métiers, délégué à la protection des données (DPO).\n- Le DPO informe, conseille et contrôle le respect des règles de protection des données personnelles ; il n'autorise pas lui-même chaque partage."}],"legende":"Modèle pédagogique : ces familles ne décrivent pas l'organigramme officiel de l'Université Paris-Saclay. Aucune ne fonctionne seule."},{"type":"activite","ref":"m05-a3"},{"type":"aretenir","texte":"La gouvernance repose sur plusieurs acteurs complémentaires, pas uniquement sur les informaticiens."}]},{"id":"m05-l4","type":"lecon","titre":"Et moi, quel est mon rôle ?","blocs":[{"type":"situation","texte":"Tu travailles dans un service administratif. Tu ne participes pas forcément aux décisions stratégiques, tu ne définis pas les règles de gestion des données et tu n'es pas informaticien.\n\nCela veut-il dire que tu n'as aucun rôle à jouer ? **Non.**"},{"type":"memo","titre":"Ma contribution, au quotidien","etapes":[{"titre":"Je saisis","texte":"Je respecte les consignes, les formats et les règles disponibles."},{"titre":"Je consulte","texte":"Je vérifie, si nécessaire, que l'information convient à l'usage prévu."},{"titre":"Je réutilise","texte":"Je cherche la bonne source et j'évite de multiplier les copies."},{"titre":"Je partage","texte":"Je respecte les conditions d'accès et les procédures."},{"titre":"Je constate une anomalie","texte":"Je la signale ou la fais vérifier par les personnes compétentes."},{"titre":"Je suis responsable de service","texte":"J'organise le travail, je veille à l'application des règles et je fais remonter les difficultés et les besoins."}]},{"type":"activite","ref":"m05-a4"},{"type":"simulateur","titre":"Qui fait quoi avec les données ?","consigne":"Cinq situations : pour chacune, choisis qui intervient principalement, puis découvre le rôle de chacun.","avertissement":"Rôles génériques, pour la réflexion : ils ne décrivent pas l'organisation officielle de l'université. En situation réelle, suis les procédures de ton service.","libelles":{"etiquette":"Jeu des rôles","icone":"👥","iconeCarte":"📌","question":"Qui doit principalement intervenir à ce stade ?","juste":"Bonne réponse","faux":"À revoir","choixJuste":"✓ Ta réponse, correcte","choixAttendu":"→ Réponse attendue","choixFaux":"✗ Ta réponse, à revoir","attendu":"Réponse attendue","manque":"Choisis une réponse avant de valider.","valider":"Valider ma réponse","reflexe":"À retenir","bilan":"bonne réponse|bonnes réponses","recommencer":"Recommencer le jeu"},"scenarios":[{"id":"regle","objectif":"os5-3","titre":"Définir une règle","contexte":"Le patrimoine, la scolarité et la logistique codent les bâtiments différemment. Il faut une règle commune.","fiche":[{"libelle":"Étape","valeur":"Définir une règle commune"}],"choix":[{"id":"a","texte":"Chaque agent, en choisissant le code qui lui paraît le plus clair.","feedback":"Des choix individuels multiplieraient les variantes."},{"id":"b","texte":"Les responsables métiers concernés et l'instance de gouvernance compétente, selon l'organisation établie.","feedback":"Oui : ceux qui connaissent les usages préparent la règle, ceux qui en ont l'autorité la valident."},{"id":"c","texte":"Le service informatique seul, puisque les codes sont dans les applications.","feedback":"Les équipes techniques mettent la règle en œuvre dans les outils, mais le sens des codes relève des métiers."}],"reponse":"b","correction":{"pourquoi":"Une règle commune engage plusieurs services : elle se construit avec eux et se valide par ceux qui en ont l'autorité.","roles":[{"role":"Responsables métiers","contribution":"expriment les besoins et proposent la règle."},{"role":"Instance de gouvernance","contribution":"valide la règle."},{"role":"Équipes techniques","contribution":"l'intègrent dans les outils."}],"reflexe":"Définir une règle commune est une décision collective, pas individuelle."}},{"id":"application","objectif":"os5-6","titre":"Appliquer une règle","contexte":"Une procédure prévoit d'écrire les dates au format AAAA-MM-JJ. Tu saisis une date.","fiche":[{"libelle":"Étape","valeur":"Saisir une information"}],"choix":[{"id":"a","texte":"Toi, l'agent chargé de la saisie : tu appliques le format prévu.","feedback":"Oui : la règle existe, l'appliquer fait partie de la saisie."},{"id":"b","texte":"Ton responsable, qui doit valider chaque saisie.","feedback":"La règle est fixée : l'appliquer ne demande pas de validation au cas par cas."},{"id":"c","texte":"Le DPO, qui contrôle la qualité des données.","feedback":"Le DPO veille à la protection des données personnelles, pas à chaque saisie."}],"reponse":"a","correction":{"pourquoi":"La gouvernance a fixé la règle ; la gestion opérationnelle l'applique. Ici, c'est toi qui agis.","roles":[{"role":"Agent","contribution":"applique le format prévu."},{"role":"Responsable ou référent","contribution":"fait connaître la règle et répond aux questions."}],"reflexe":"Quand la règle existe, je l'applique ; en cas de doute, je demande."}},{"id":"anomalie","objectif":"os5-4","titre":"Une anomalie détectée","contexte":"Une gestionnaire de bibliothèque repère deux dates d'acquisition différentes pour un même document, dans deux fichiers.","fiche":[{"libelle":"Étape","valeur":"Une incohérence est repérée"}],"choix":[{"id":"a","texte":"La gestionnaire : elle signale l'anomalie ou demande une vérification selon la procédure.","feedback":"Oui : repérer et signaler, c'est déjà contribuer à la qualité."},{"id":"b","texte":"La gestionnaire : elle choisit la date qui lui semble juste et corrige les deux fichiers.","feedback":"Corriger sans vérifier peut remplacer une erreur par une autre."},{"id":"c","texte":"Personne : ce n'est pas son fichier.","feedback":"Sans signalement, l'erreur continuera de circuler."}],"reponse":"a","correction":{"pourquoi":"Le traitement dépend des responsabilités définies ; le premier pas, c'est le signalement.","roles":[{"role":"Gestionnaire","contribution":"signale l'anomalie et la décrit précisément."},{"role":"Responsable du fichier ou référent","contribution":"vérifie la source et corrige."}],"reflexe":"Je signale ce que je repère ; je ne corrige que ce qui relève de mon périmètre."}},{"id":"technique","objectif":"os5-5","titre":"Un problème technique","contexte":"L'application refuse d'enregistrer un code de structure pourtant prévu dans le référentiel.","fiche":[{"libelle":"Étape","valeur":"L'outil bloque une saisie conforme à la règle"}],"choix":[{"id":"a","texte":"Le service informatique seul : c'est un problème de logiciel.","feedback":"Les équipes techniques analysent l'outil, mais le service métier doit confirmer ce qui est attendu."},{"id":"b","texte":"Le service métier concerné et les équipes techniques compétentes, chacun selon ses responsabilités.","feedback":"Oui : le métier confirme la règle, la technique analyse et corrige l'outil."},{"id":"c","texte":"L'agent qui saisit, en choisissant un code proche que l'application accepte.","feedback":"Un code de contournement créerait une incohérence de plus."}],"reponse":"b","correction":{"pourquoi":"Un problème technique a souvent une part métier : que doit contenir la donnée, et pourquoi l'outil la refuse-t-il ?","roles":[{"role":"Agent","contribution":"signale le blocage avec un exemple précis."},{"role":"Service métier","contribution":"confirme la règle attendue."},{"role":"Équipes techniques","contribution":"analysent et corrigent l'application."}],"reflexe":"Problème d'outil : métier et technique travaillent ensemble."}},{"id":"arbitrage","objectif":"os5-4","titre":"Des besoins qui divergent","contexte":"Pour nommer les formations, un service veut des libellés courts, un autre des libellés détaillés.","fiche":[{"libelle":"Étape","valeur":"Arbitrer entre deux besoins légitimes"}],"choix":[{"id":"a","texte":"Le service qui a créé son fichier en premier.","feedback":"L'ancienneté d'un fichier ne donne pas d'autorité pour décider."},{"id":"b","texte":"Les responsables ou instances qui ont l'autorité d'arbitrage définie par la gouvernance.","feedback":"Oui : arbitrer fait partie du rôle de la gouvernance."},{"id":"c","texte":"Personne : chaque service garde sa version.","feedback":"Sans arbitrage, deux règles coexistent et les données ne se rapprochent plus."}],"reponse":"b","correction":{"pourquoi":"Quand des besoins légitimes s'opposent, il faut savoir à l'avance qui tranche.","roles":[{"role":"Services concernés","contribution":"exposent leurs besoins."},{"role":"Responsables ou instance d'arbitrage","contribution":"décident (par exemple : un libellé de référence et une correspondance) et expliquent leur choix."},{"role":"Tous","contribution":"appliquent la décision."}],"reflexe":"Quand des besoins divergent, on fait arbitrer ; on ne tranche pas seul."}}],"conclusion":"La gouvernance est collective : chacun y a un rôle, à son niveau, et les rôles se complètent."},{"type":"aretenir","texte":"Je contribue à la gouvernance des données à mon niveau, par mes pratiques et par mon expertise métier."}]},{"id":"m05-defi","type":"evaluation","titre":"Le défi du module","surtitre":"Défi final","libelleAcces":"Relever le défi","libelleRecommencer":"Recommencer le défi","presentation":"une-par-une","introduction":"Quatre questions, une à la fois. Tu découvres la correction après chaque réponse, et tu peux recommencer le défi autant de fois que tu le souhaites.","activites":["m05-q1","m05-q2","m05-q3","m05-q4"],"messagesResultat":[{"min":100,"texte":"Bravo ! Tu as compris que la gouvernance est une organisation collective, et que tu y contribues à ton niveau."},{"min":75,"texte":"Très bien. Relis la correction de la question à revoir : elle reprend une idée clé du module."},{"min":50,"texte":"C'est un bon début. Les corrections t'aideront à distinguer gouvernance et gestion, et à repérer le rôle de chacun."},{"min":0,"texte":"Ces notions sont nouvelles pour beaucoup de personnes. Prends le temps de relire les corrections, puis recommence le défi quand tu le souhaites."}]}],"activites":{"m05-a1":{"type":"choix-unique","objectif":"os5-1","notation":{"formative":true,"points":1},"consigne":"Plusieurs services utilisent des codes différents pour désigner une même catégorie de locaux. Quelle démarche favorise une meilleure cohérence ?","choix":[{"id":"a","texte":"Imposer immédiatement à tous les services de supprimer leurs fichiers.","feedback":"Supprimer des fichiers utiles ne crée pas de règle commune, et ferait perdre des informations."},{"id":"b","texte":"Définir collectivement une règle ou une correspondance de référence adaptée.","feedback":"C'est la démarche de la gouvernance : une référence commune, construite avec les services concernés."},{"id":"c","texte":"Laisser chacun créer de nouveaux codes sans coordination.","feedback":"De nouveaux codes ajouteraient des variantes, sans rapprocher les informations."}],"reponse":"b","explication":{"correct":"La gouvernance aide à établir des règles communes ou des correspondances lorsque plusieurs services doivent utiliser ou rapprocher leurs données.","incorrect":"La bonne réponse est la deuxième. La gouvernance aide à établir des règles communes ou des correspondances lorsque plusieurs services doivent utiliser ou rapprocher leurs données."}},"m05-a2":{"type":"classement","objectif":"os5-2","notation":{"formative":true,"points":1},"consigne":"Gouvernance ou gestion opérationnelle ? Pour chaque action, choisis le niveau principalement concerné.","categories":[{"id":"g","texte":"Gouvernance"},{"id":"o","texte":"Gestion opérationnelle"}],"elements":[{"id":"1","texte":"Définir une règle commune de nommage des bâtiments.","categorie":"g","explication":"Fixer une règle commune relève du cadre."},{"id":"2","texte":"Corriger une date erronée dans un fichier.","categorie":"o","explication":"C'est une action concrète sur la donnée."},{"id":"3","texte":"Saisir une nouvelle inscription étudiante.","categorie":"o","explication":"La saisie applique les règles prévues."},{"id":"4","texte":"Définir qui valide les informations de référence.","categorie":"g","explication":"Attribuer une responsabilité relève de la gouvernance."},{"id":"5","texte":"Signaler une incohérence entre deux applications.","categorie":"o","explication":"Signaler fait partie des gestes du quotidien… et alimente la gouvernance."},{"id":"6","texte":"Déterminer les conditions générales d'attribution des accès.","categorie":"g","explication":"Fixer des principes d'accès relève du cadre ; les accorder relève ensuite de la gestion."}],"explication":{"correct":"Bravo. La gouvernance organise le cadre commun ; la gestion opérationnelle correspond à son application quotidienne. Les deux sont nécessaires, et certaines actions se situent à l'interface.","incorrect":"Certaines réponses sont à revoir : les explications ci-dessus précisent le niveau principalement concerné. La gouvernance organise le cadre commun ; la gestion opérationnelle l'applique au quotidien. La frontière n'est pas toujours nette."}},"m05-a3":{"type":"choix-unique","objectif":"os5-6","notation":{"formative":true,"points":1},"consigne":"Un agent constate qu'un code de formation semble incorrect dans une application. Quel est son premier réflexe ?","choix":[{"id":"a","texte":"Modifier immédiatement tous les fichiers de l'université.","feedback":"Il n'a ni les droits ni la certitude nécessaires : une correction en masse pourrait propager une erreur."},{"id":"b","texte":"Signaler ou faire vérifier l'anomalie selon la procédure prévue.","feedback":"C'est le bon réflexe : signaler permet aux personnes compétentes de vérifier et de corriger."},{"id":"c","texte":"Ignorer l'erreur, car la qualité relève uniquement du service informatique.","feedback":"La qualité n'est pas l'affaire du seul service informatique : ceux qui utilisent la donnée sont souvent les premiers à voir l'erreur."}],"reponse":"b","explication":{"correct":"Les agents contribuent à la qualité des données en identifiant et en signalant les anomalies. Leur traitement dépend ensuite des responsabilités et des procédures établies.","incorrect":"La bonne réponse est la deuxième. Les agents contribuent à la qualité des données en identifiant et en signalant les anomalies. Leur traitement dépend ensuite des responsabilités et des procédures établies."}},"m05-a4":{"type":"choix-unique","objectif":"os5-6","notation":{"formative":true,"points":1},"consigne":"Un agent constate que plusieurs collègues utilisent des tableaux locaux aux informations contradictoires. Quelle attitude est la plus utile ?","choix":[{"id":"a","texte":"Imposer seul un nouveau fichier à l'ensemble des services.","feedback":"Un fichier de plus, imposé sans concertation, risque d'ajouter une version au lieu d'en supprimer."},{"id":"b","texte":"Signaler la difficulté et rechercher, avec les personnes compétentes, la source de référence et les règles communes.","feedback":"C'est la démarche la plus utile : faire remonter le problème pour qu'il soit traité à la source."},{"id":"c","texte":"Continuer sans rien signaler, car la gouvernance relève exclusivement de la direction.","feedback":"La direction ne peut pas traiter ce qu'elle ne connaît pas : les remontées du terrain sont indispensables."}],"reponse":"b","explication":{"correct":"La gouvernance est collective. Les agents contribuent à son efficacité en faisant remonter les besoins et les difficultés rencontrées sur le terrain.","incorrect":"La bonne réponse est la deuxième. La gouvernance est collective. Les agents contribuent à son efficacité en faisant remonter les besoins et les difficultés rencontrées sur le terrain."}},"m05-q1":{"type":"choix-unique","objectif":"os5-1","notation":{"formative":false,"points":1},"consigne":"À quoi sert principalement la gouvernance de la donnée ?","choix":[{"id":"a","texte":"À remplacer tous les logiciels existants."},{"id":"b","texte":"À organiser les règles, les responsabilités et les décisions concernant les données."},{"id":"c","texte":"À confier toutes les données au seul service informatique."}],"reponse":"b","explication":{"correct":"La gouvernance définit un cadre commun pour organiser la gestion et l'utilisation des données. Les outils informatiques contribuent à son application, mais n'en constituent pas l'unique objet.","incorrect":"La bonne réponse est la deuxième. La gouvernance définit un cadre commun pour organiser la gestion et l'utilisation des données. Les outils informatiques contribuent à son application, mais n'en constituent pas l'unique objet."}},"m05-q2":{"type":"choix-unique","objectif":"os5-2","notation":{"formative":false,"points":1},"consigne":"Une université définit une règle commune pour identifier ses bâtiments. Cette action relève principalement :","choix":[{"id":"a","texte":"De la gouvernance."},{"id":"b","texte":"De la saisie quotidienne."},{"id":"c","texte":"De la maintenance informatique."}],"reponse":"a","explication":{"correct":"Définir une règle commune relève du cadre de gouvernance. La renseigner et l'appliquer dans les outils relève ensuite de la gestion opérationnelle.","incorrect":"La bonne réponse est la gouvernance. Définir une règle commune relève du cadre de gouvernance. La renseigner et l'appliquer dans les outils relève ensuite de la gestion opérationnelle."}},"m05-q3":{"type":"choix-unique","objectif":"os5-4","notation":{"formative":false,"points":1},"consigne":"Un agent constate une incohérence dans une donnée qu'il utilise. Quelle démarche est la plus appropriée ?","choix":[{"id":"a","texte":"Ignorer le problème."},{"id":"b","texte":"Supprimer toutes les données concernées."},{"id":"c","texte":"Signaler ou faire vérifier l'anomalie selon les procédures applicables."}],"reponse":"c","explication":{"correct":"La qualité des données est une responsabilité collective. Signaler une difficulté permet aux personnes compétentes de la traiter.","incorrect":"La bonne réponse est la troisième. La qualité des données est une responsabilité collective. Signaler une difficulté permet aux personnes compétentes de la traiter."}},"m05-q4":{"type":"choix-unique","objectif":"os5-5","notation":{"formative":false,"points":1},"consigne":"Pourquoi les services métiers doivent-ils participer à la gouvernance des données ?","choix":[{"id":"a","texte":"Parce qu'ils connaissent les activités, les besoins et les usages des données."},{"id":"b","texte":"Parce qu'ils doivent tous devenir informaticiens."},{"id":"c","texte":"Parce qu'ils doivent pouvoir décider seuls de toutes les règles."}],"reponse":"a","explication":{"correct":"L'expertise métier est indispensable pour définir des règles adaptées aux réalités du terrain et aux besoins collectifs.","incorrect":"La bonne réponse est la première. L'expertise métier est indispensable pour définir des règles adaptées aux réalités du terrain et aux besoins collectifs."}}},"synthese":["La gouvernance ne se limite pas à l'informatique.","Elle définit des règles, des responsabilités et des modalités de décision.","La gestion opérationnelle applique ces règles au quotidien.","Les services métiers participent à la définition des besoins et des règles.","Chaque agent contribue à la qualité et à l'utilisation responsable des données."]},"m06":{"id":"m06","numero":6,"titre":"Les bons réflexes professionnels","sousTitre":"Adopter les bons réflexes pour rechercher, saisir, contrôler, utiliser et partager les données.","slugArchive":"bons-reflexes-professionnels","duree":10,"statutContenu":"proposition - à valider (procédures et interlocuteurs à confirmer avec les services)","objectif":"Reconnaître les bonnes pratiques de gestion des données et comprendre comment les appliquer au quotidien, selon son rôle et les procédures de l'établissement.","objectifsSpecifiques":[{"id":"os6-1","texte":"Identifier le bon réflexe avant de créer un nouveau fichier."},{"id":"os6-2","texte":"Reconnaître l'intérêt de rechercher une source de référence."},{"id":"os6-3","texte":"Comprendre l'importance des règles de saisie et de structuration."},{"id":"os6-4","texte":"Identifier la conduite à adopter lorsqu'une information semble incorrecte ou incomplète."},{"id":"os6-5","texte":"Reconnaître les précautions nécessaires avant de partager une donnée."},{"id":"os6-6","texte":"Comprendre l'importance de documenter certaines informations et de signaler les anomalies."},{"id":"os6-7","texte":"Identifier sa propre contribution à la gestion collective des données."}],"validation":{"navigation":"sequentielle","leconsObligatoires":true,"evaluation":"m06-defi"},"lecons":[{"id":"m06-l1","type":"lecon","titre":"Avant de créer, je vérifie ce qui existe","blocs":[{"type":"situation","texte":"Sophie doit préparer une liste de bâtiments pour une intervention de Noé. Premier réflexe : « Je crée un nouveau fichier. » C'est rapide… mais l'inventaire de Noé existe peut-être déjà."},{"type":"decision","id":"m06-d1","consigne":"Sophie a besoin de la liste des bâtiments. Que fait-elle ?","donnee":"inventaire-batiments","choix":[{"id":"a","texte":"Elle crée tout de suite un nouveau fichier.","implication":"Un tableau de plus vient de naître. Dès la prochaine mise à jour de l'inventaire de Noé, les deux listes divergeront.","trace":"Nouveau fichier de bâtiments, à côté de l'inventaire de Noé.","etat":"La liste existe en deux endroits."},{"id":"b","texte":"Elle vérifie d'abord si l'inventaire de Noé répond au besoin.","implication":"La donnée existe déjà. Sophie la cherche avant d'en créer une autre. S'il manque quelque chose, elle le saura.","etat":"Sophie consulte l'inventaire de Noé. Aucune copie nouvelle."}]},{"type":"texte","titre":"Si chaque service crée son propre fichier","texte":"- les copies se multiplient et ne sont plus synchronisées ;\n- les mêmes mises à jour sont faites plusieurs fois ;\n- on risque d'utiliser une version ancienne ;\n- on ne sait plus quelle source est fiable ;\n- on perd du temps à rapprocher les fichiers.\n\nUn fichier local n'est pas mauvais en soi : il peut répondre à un besoin précis ou temporaire. Le problème naît quand il devient une **source parallèle** que personne ne maîtrise."},{"type":"memo","etiquette":"Arbre de décision","titre":"Avant de créer un fichier","disposition":"enchainement","etapes":[{"titre":"J'ai besoin d'une information","texte":"Ai-je réellement besoin d'un nouveau fichier ?"},{"titre":"Je vérifie si elle existe","texte":"Cette donnée existe-t-elle déjà ?"},{"titre":"J'identifie la source","texte":"Existe-t-il une source ou un référentiel approprié ? Qui peut m'orienter ?"},{"titre":"Je vérifie les conditions d'utilisation","texte":"Puis-je l'utiliser pour mon besoin, dans les conditions prévues ?"},{"titre":"J'utilise l'existant… ou je justifie un nouveau support","texte":"Si rien ne convient, je crée un fichier en sachant pourquoi, et d'où viennent les données."}]},{"type":"activite","ref":"m06-a1"},{"type":"aretenir","texte":"Avant de recréer une donnée, je vérifie si elle existe déjà et comment y accéder correctement."}]},{"id":"m06-l2","type":"lecon","titre":"Je saisis, contrôle et actualise avec rigueur","blocs":[{"type":"situation","texte":"Tu travailles au service de scolarité. Tu enregistres une inscription : le formulaire demande un code de formation et une date d'inscription. Certaines informations reçues sont ambiguës. Que faire ?"},{"type":"texte","titre":"Six réflexes de saisie","texte":"- **Respecter les formats** : le format de date prévu par l'application.\n- **Utiliser les valeurs de référence** : le code de formation du référentiel.\n- **Vérifier** : contrôler un identifiant quand une incohérence apparaît.\n- **Ne pas inventer** : pas de date approximative pour remplir un champ obligatoire.\n- **Actualiser, quand cela relève de ta mission** : modifier un statut qui a changé, si la procédure le prévoit.\n- **Signaler** : prévenir l'interlocuteur compétent quand une donnée semble contradictoire."},{"type":"comparateur","titre":"Deux façons de remplir le même formulaire","consigne":"Sélectionne une valeur du formulaire A, ou une difficulté de la liste, pour comprendre ce qui pose problème. Examine les quatre difficultés.","libelles":{"avant":"Avant : le formulaire rempli","difficultes":"Les difficultés à repérer","aide":"Examine les {n} difficultés pour découvrir le formulaire rempli avec rigueur.","voirApres":"Voir le formulaire rempli avec rigueur","apres":"Après : une saisie rigoureuse","atouts":"Ce que cette saisie apporte :"},"avant":{"titre":"Formulaire A : saisie rapide","colonnes":["Champ","Valeur saisie"],"lignes":[["Code de formation","licence info 3"],["Date d'inscription","début septembre"],["Numéro étudiant","2026 0453"],["Régime d'inscription","?"]],"legende":"Formulaire fictif."},"problemes":[{"id":"code-libre","libelle":"Un code saisi librement","explication":"Écrit à la main, le code ne correspond à aucune valeur du **référentiel** : la formation ne sera pas reconnue dans les comptages.","cellules":[[0,1]]},{"id":"date-approx","libelle":"Une date approximative","explication":"« Début septembre » n'est pas une date : impossible de trier, de calculer un délai ou de vérifier une échéance.","cellules":[[1,1]]},{"id":"non-verifie","libelle":"Une information non vérifiée","explication":"Le numéro a été recopié sans contrôle : une erreur d'un chiffre rattacherait l'inscription à un autre étudiant.","cellules":[[2,1]]},{"id":"ambigu","libelle":"Un champ laissé ambigu","explication":"Un « ? » sera lu comme une valeur. Mieux vaut un champ clairement non renseigné, et signalé.","cellules":[[3,1]]}],"apres":{"titre":"Formulaire B : bonnes pratiques","colonnes":["Champ","Valeur saisie"],"lignes":[["Code de formation","Sélectionné dans la liste de référence"],["Date d'inscription","Date exacte, vérifiée sur le document source, au format prévu"],["Numéro étudiant","Contrôlé dans l'application"],["Régime d'inscription","Non renseigné : information demandée au service compétent"]],"legende":"Formulaire fictif.","atouts":["Valeurs cohérentes avec le référentiel","Informations vérifiées","Ce qui manque est signalé, pas deviné"],"avertissement":"Le formulaire B ne corrige rien par supposition : une information qu'on ne peut pas vérifier est signalée, jamais inventée."}},{"type":"activite","ref":"m06-a2"},{"type":"aretenir","texte":"Je contribue à la qualité des données en respectant les règles de saisie, en vérifiant les informations et en signalant les anomalies."}]},{"id":"m06-l3","type":"lecon","titre":"Je partage, documente et signale","blocs":[{"type":"situation","texte":"Tu tiens un tableau de suivi utilisé par plusieurs collègues, et tu dois le transmettre à un autre service. Trois questions se posent :\n\n- Ces données peuvent-elles être transmises ?\n- Le collègue saura-t-il les comprendre ?\n- Resteront-elles utilisables après ton départ ou ton changement de poste ?"},{"type":"texte","titre":"Partager de manière responsable","texte":"Comme vu au module 4 : comprendre le besoin, vérifier les conditions d'accès, limiter les données au nécessaire, utiliser un moyen de transmission adapté."},{"type":"definition","terme":"Métadonnée","texte":"Information qui décrit une donnée ou un ensemble de données : signification des colonnes, origine, date de dernière mise à jour, unité, sens des codes, limites connues."},{"type":"exemple","titre":"Une précision qui change tout","texte":"Dans un tableau d'effectifs, indiquer : « étudiants inscrits administrativement au 15 octobre ». Sans cette mention, deux services peuvent comparer des chiffres qui ne mesurent pas la même chose.\n\nTout ne doit pas être documenté par chacun : ce qui est utile dépend des usages, des règles et de ton rôle."},{"type":"texte","titre":"Signaler, sans forcément tout corriger","texte":"Une information incohérente, un doublon possible, une donnée manquante, un écart entre deux sources, une procédure peu claire : tu n'as pas à tout corriger toi-même. **Signaler** le problème aux personnes compétentes est souvent la bonne démarche."},{"type":"activite","ref":"m06-a3"},{"type":"aretenir","texte":"Une donnée utile doit pouvoir être comprise, utilisée dans les bonnes conditions et corrigée lorsqu'un problème est détecté."}]},{"id":"m06-l4","type":"lecon","titre":"Simulation : une journée avec les données","blocs":[{"type":"situation","texte":"Tu es agent administratif. Au fil d'une journée, cinq situations se présentent, dans différents services. Pour chacune, choisis ce que tu fais. Prends ton temps : il n'y a pas de chronomètre, les horaires servent seulement à raconter la journée."},{"type":"simulateur","titre":"Une journée avec les données","consigne":"Cinq situations, une à la fois. Après chaque choix, découvre l'explication et le réflexe associé.","avertissement":"Situations fictives, pour s'entraîner. En situation réelle, suis les procédures de ton service et demande conseil en cas de doute.","bilanReflexes":true,"libelles":{"etiquette":"Simulation","icone":"📅","iconeCarte":"","question":"Que fais-tu ?","juste":"Bon réflexe","faux":"À revoir","choixJuste":"✓ Ton choix, bon réflexe","choixAttendu":"→ Réponse attendue","choixFaux":"✗ Ton choix, à revoir","attendu":"Réponse attendue","manque":"Choisis une réponse avant de valider.","valider":"Valider mon choix","reflexe":"Réflexe associé","bilan":"bon réflexe|bons réflexes","recommencer":"Recommencer la journée","revoir":"Revoir les situations"},"scenarios":[{"id":"nouveau-tableau","heure":"9 h","objectif":"os6-1","titre":"Un nouveau tableau à créer","contexte":"Sophie doit préparer une liste de bâtiments pour une intervention de Noé. Un collègue t'indique que son inventaire existe déjà.","fiche":[{"libelle":"Service","valeur":"Patrimoine et maintenance"}],"choix":[{"id":"a","texte":"Je crée immédiatement une nouvelle liste, sans consulter l'inventaire.","feedback":"Une liste de plus, qui risque de diverger de l'inventaire dès la prochaine mise à jour."},{"id":"b","texte":"Je vérifie si l'inventaire existant répond au besoin et si je peux l'utiliser.","feedback":"Oui : c'est la démarche de l'arbre de décision."},{"id":"c","texte":"Je reprends un ancien tableau trouvé dans un dossier personnel, sans vérifier sa date.","feedback":"Un ancien tableau peut contenir des bâtiments fermés ou oublier les nouveaux."}],"carnet":{"donnee":"inventaire-batiments","effets":{"a":{"trace":"Une nouvelle liste de bâtiments a été créée, sans consulter l'inventaire de Noé.","etat":"La liste existe en deux endroits."},"b":{"etat":"L'inventaire de Noé a été consulté avant de créer quoi que ce soit."},"c":{"trace":"Un ancien tableau personnel a été repris, sans date de mise à jour.","etat":"La liste utilisée n'est peut-être plus celle de l'inventaire."}}},"reponse":"b","correction":{"pourquoi":"Avant de créer un fichier, il est utile de rechercher les données existantes : on limite les versions parallèles et on utilise des informations mieux maîtrisées.","reflexe":"Rechercher avant de recréer."}},{"id":"contradiction","heure":"10 h","objectif":"os6-4","titre":"Une information contradictoire","contexte":"Tu prépares une liste d'agents. Le dossier de Julie et le fichier de Sophie ne donnent pas la même affectation pour Camille.","fiche":[{"libelle":"Service","valeur":"Ressources humaines"}],"choix":[{"id":"a","texte":"Je choisis l'affectation qui semble la plus probable.","feedback":"Une supposition peut devenir une erreur, puis être reprise par d'autres."},{"id":"b","texte":"Je vérifie l'information auprès de la source ou du service compétent.","feedback":"Oui : on lève le doute à la source avant d'utiliser la donnée."},{"id":"c","texte":"Je garde les deux informations sans signaler la contradiction.","feedback":"L'écart restera, et chaque utilisateur devra le découvrir à son tour."}],"carnet":{"donnee":"arrivee-camille","effets":{"a":{"trace":"Une affectation supposée a été choisie pour Camille.","etat":"L'affectation de Camille n'a pas été vérifiée à la source."},"b":{"etat":"L'affectation de Camille a été vérifiée auprès de Julie."},"c":{"trace":"Les deux affectations de Camille ont été conservées, sans signalement.","etat":"L'écart reste, chacun le redécouvrira."}}},"reponse":"b","correction":{"pourquoi":"Quand une information semble contradictoire, on recherche la source appropriée et on fait vérifier l'écart avant de réutiliser la donnée.","reflexe":"Vérifier avant d'utiliser."}},{"id":"date-manquante","heure":"11 h","objectif":"os6-3","titre":"Une date manquante","contexte":"Tu dois enregistrer la date de l'intervention de Noé sur la chaudière. Elle ne figure pas dans le document transmis.","fiche":[{"libelle":"Service","valeur":"Maintenance des équipements"}],"choix":[{"id":"a","texte":"Je renseigne une date approximative.","feedback":"Une date approximative sera lue comme exacte, par exemple pour planifier la prochaine intervention."},{"id":"b","texte":"Je copie la date de la dernière intervention sur un équipement voisin.","feedback":"C'est la date d'un autre équipement : l'historique de celui-ci deviendrait faux."},{"id":"c","texte":"Je recherche l'information ou je signale son absence selon la procédure prévue.","feedback":"Oui : un champ manquant et signalé vaut mieux qu'une valeur inventée."}],"carnet":{"donnee":"intervention","effets":{"a":{"trace":"Une date approximative a été notée pour l'intervention de Noé.","etat":"La date sera lue comme exacte."},"b":{"trace":"La date d'un équipement voisin a été copiée.","etat":"L'historique de l'équipement est faux."},"c":{"etat":"La date de Noé manque, et c'est signalé. Elle n'a pas été inventée."}}},"reponse":"c","correction":{"pourquoi":"Une donnée non vérifiée ne doit pas être inventée : une information incorrecte peut être réutilisée et créer d'autres difficultés.","reflexe":"Ne pas inventer une donnée."}},{"id":"demande-partage","heure":"14 h","objectif":"os6-5","titre":"Une demande de partage","contexte":"Un collègue d'un autre service demande une extraction contenant des informations individuelles sur des agents. Il ne précise pas son besoin.","fiche":[{"libelle":"Service","valeur":"Administration générale"}],"choix":[{"id":"a","texte":"Je transmets le fichier tout de suite : il travaille dans la même université.","feedback":"Travailler dans le même établissement ne donne pas accès à toutes les données."},{"id":"b","texte":"Je vérifie la finalité de la demande, les autorisations et les règles applicables.","feedback":"Oui : on comprend le besoin avant de transmettre, et seulement ce qui est nécessaire."},{"id":"c","texte":"Je diffuse le fichier à l'ensemble des services, par transparence.","feedback":"Des informations individuelles seraient exposées à des personnes qui n'en ont pas besoin."}],"carnet":{"donnee":"remunerations","effets":{"a":{"trace":"Un fichier individuel a été transmis sans que le besoin soit précisé.","etat":"Des informations individuelles ont quitté leur service."},"b":{"etat":"Rien n'est transmis tant que le besoin et les droits ne sont pas vérifiés."},"c":{"trace":"Le fichier a été diffusé à l'ensemble des services.","etat":"Des informations individuelles sont parties trop loin."}}},"reponse":"b","correction":{"pourquoi":"Le partage responsable demande de comprendre le besoin, de vérifier les autorisations et de limiter la transmission au nécessaire.","reflexe":"Partager dans les bonnes conditions."}},{"id":"tableau-documente","heure":"16 h","objectif":"os6-6","titre":"Un tableau à transmettre","contexte":"Tu transmets un tableau des effectifs étudiants par formation. Les chiffres sont justes, mais rien n'indique la date de référence ni la façon dont ils ont été calculés.","fiche":[{"libelle":"Service","valeur":"Scolarité, pour le service finances et pilotage"}],"choix":[{"id":"a","texte":"Je transmets sans précision : les chiffres suffisent.","feedback":"Sans date ni périmètre, le destinataire peut les comparer à des chiffres calculés autrement."},{"id":"b","texte":"J'ajoute ce qu'il faut pour les interpréter, notamment la date et le périmètre du calcul.","feedback":"Oui : deux lignes suffisent souvent à éviter un contresens."},{"id":"c","texte":"Je supprime les intitulés de colonnes pour alléger le fichier.","feedback":"Sans intitulés, le tableau devient illisible pour tout autre que toi."}],"carnet":{"donnee":"effectifs-etudiants","effets":{"a":{"trace":"Le tableau des effectifs est parti sans date ni périmètre.","etat":"Le chiffre peut être comparé à un autre, calculé autrement."},"b":{"etat":"La date et le périmètre accompagnent les effectifs."},"c":{"trace":"Les intitulés de colonnes ont été retirés.","etat":"Le tableau n'est plus compréhensible sans toi."}}},"reponse":"b","correction":{"pourquoi":"Documenter l'essentiel permet aux autres utilisateurs de comprendre les données et de les réutiliser sans ambiguïté.","reflexe":"Documenter pour faciliter la réutilisation."}}],"conclusion":"Cinq situations, cinq réflexes simples. Aucun ne demande d'outil complexe : ils s'adaptent à ton métier et aux règles de l'établissement. Et en cas de doute, demander conseil fait aussi partie des bons réflexes."},{"type":"fiche"},{"type":"aretenir","texte":"Bien gérer les données commence par des réflexes simples, adaptés à mon métier et aux règles de l'établissement."}]},{"id":"m06-defi","type":"evaluation","titre":"Le défi du module","surtitre":"Défi final","libelleAcces":"Relever le défi","libelleRecommencer":"Recommencer le défi","presentation":"une-par-une","introduction":"Cinq questions, une à la fois. Tu découvres la correction après chaque réponse, et tu peux recommencer le défi autant de fois que tu le souhaites.","activites":["m06-q1","m06-q2","m06-q3","m06-q4","m06-q5"],"messagesResultat":[{"min":100,"texte":"Bravo ! Tu as les bons réflexes pour rechercher, vérifier, respecter les règles, partager et documenter."},{"min":80,"texte":"Très bien. Relis la correction de la question à revoir : elle correspond à l'un des cinq réflexes."},{"min":60,"texte":"C'est un bon début. Les corrections et la fiche mémo t'aideront à fixer les réflexes à revoir."},{"min":0,"texte":"Ces réflexes s'acquièrent avec la pratique. Relis les corrections, garde la fiche mémo sous la main, puis recommence le défi quand tu le souhaites."}]}],"activites":{"m06-a1":{"type":"choix-unique","objectif":"os6-2","notation":{"formative":true,"points":1},"consigne":"Tu dois préparer un tableau d'effectifs. Un collègue t'indique qu'une source institutionnelle existe déjà. Quelle démarche privilégier ?","choix":[{"id":"a","texte":"Créer immédiatement ton propre fichier, sans vérifier.","feedback":"Un fichier de plus, qui risque de s'écarter de la source institutionnelle."},{"id":"b","texte":"Vérifier si la source existante répond à ton besoin et si tu es autorisé à l'utiliser.","feedback":"C'est le bon réflexe."},{"id":"c","texte":"Copier plusieurs anciens tableaux et choisir le plus complet.","feedback":"Le plus complet n'est pas forcément le plus juste, ni le plus récent."}],"reponse":"b","explication":{"correct":"Rechercher les informations existantes permet de limiter les copies inutiles, les écarts de version et les corrections répétées.","incorrect":"La bonne réponse est la deuxième. Rechercher les informations existantes permet de limiter les copies inutiles, les écarts de version et les corrections répétées."}},"m06-a2":{"type":"choix-unique","objectif":"os6-7","notation":{"formative":true,"points":1},"consigne":"Un formulaire demande une date, mais le document source contient une information contradictoire. Que fais-tu ?","choix":[{"id":"a","texte":"Je saisis la date qui paraît la plus vraisemblable.","feedback":"Une date « vraisemblable » sera ensuite considérée comme exacte."},{"id":"b","texte":"Je vérifie la source ou je signale l'incohérence selon la procédure prévue.","feedback":"C'est ta contribution à la qualité : vérifier ou signaler."},{"id":"c","texte":"Je copie la date d'un autre dossier.","feedback":"La date d'un autre dossier n'a aucune raison d'être la bonne."}],"reponse":"b","explication":{"correct":"Une information incertaine doit être vérifiée ou signalée. Une valeur inventée pourrait ensuite être considérée comme exacte et réutilisée dans d'autres traitements.","incorrect":"La bonne réponse est la deuxième. Une information incertaine doit être vérifiée ou signalée. Une valeur inventée pourrait ensuite être considérée comme exacte et réutilisée dans d'autres traitements."}},"m06-a3":{"type":"choix-unique","objectif":"os6-6","notation":{"formative":true,"points":1},"consigne":"Tu transmets un tableau d'effectifs à un service autorisé. Quelle information complémentaire peut faciliter son interprétation ?","choix":[{"id":"a","texte":"La date de référence et la définition des effectifs comptabilisés.","feedback":"Exactement : ce sont des métadonnées utiles."},{"id":"b","texte":"Le nombre de fois où tu as ouvert le tableur.","feedback":"Cette information n'aide pas à comprendre les chiffres."},{"id":"c","texte":"La couleur préférée de la personne qui a créé le tableau.","feedback":"Cette information n'aide pas à comprendre les chiffres."}],"reponse":"a","explication":{"correct":"La date de référence et les règles de calcul permettent de comprendre ce que représentent réellement les chiffres. Ce sont des informations utiles pour interpréter et réutiliser les données.","incorrect":"La bonne réponse est la première. La date de référence et les règles de calcul permettent de comprendre ce que représentent réellement les chiffres."}},"m06-q1":{"type":"choix-unique","objectif":"os6-1","notation":{"formative":false,"points":1},"consigne":"Avant de créer un nouveau tableau de suivi, quelle démarche est préférable ?","choix":[{"id":"a","texte":"Vérifier si les données existent déjà dans une source appropriée."},{"id":"b","texte":"Créer systématiquement une copie indépendante."},{"id":"c","texte":"Rassembler tous les anciens fichiers sans vérification."}],"reponse":"a","explication":{"correct":"Rechercher les données existantes permet de limiter les fichiers parallèles et les risques de divergence.","incorrect":"La bonne réponse est la première. Rechercher les données existantes permet de limiter les fichiers parallèles et les risques de divergence."}},"m06-q2":{"type":"choix-unique","objectif":"os6-4","notation":{"formative":false,"points":1},"consigne":"Une information te semble incorrecte. Que fais-tu ?","choix":[{"id":"a","texte":"Je la modifie au hasard."},{"id":"b","texte":"Je la vérifie ou je signale l'anomalie selon la procédure prévue."},{"id":"c","texte":"Je la copie dans un nouveau fichier."}],"reponse":"b","explication":{"correct":"Vérifier ou signaler une anomalie contribue à maintenir la fiabilité des données.","incorrect":"La bonne réponse est la deuxième. Vérifier ou signaler une anomalie contribue à maintenir la fiabilité des données."}},"m06-q3":{"type":"choix-unique","objectif":"os6-3","notation":{"formative":false,"points":1},"consigne":"Deux fichiers utilisent des codes différents pour une même catégorie de formation. Quel est le bon réflexe ?","choix":[{"id":"a","texte":"Choisir le code le plus court."},{"id":"b","texte":"Inventer un troisième code."},{"id":"c","texte":"Vérifier le référentiel ou la nomenclature applicable."}],"reponse":"c","explication":{"correct":"Un référentiel commun permet d'utiliser des désignations cohérentes et de faciliter le rapprochement des données.","incorrect":"La bonne réponse est la troisième. Un référentiel commun permet d'utiliser des désignations cohérentes et de faciliter le rapprochement des données."}},"m06-q4":{"type":"choix-unique","objectif":"os6-5","notation":{"formative":false,"points":1},"consigne":"Un service demande des informations individuelles sans expliquer leur utilisation. Quelle attitude est préférable ?","choix":[{"id":"a","texte":"Envoyer immédiatement le fichier."},{"id":"b","texte":"Vérifier le besoin, les autorisations et les règles de partage."},{"id":"c","texte":"Publier les informations sur un espace accessible à tous."}],"reponse":"b","explication":{"correct":"La transmission doit répondre à une finalité appropriée et respecter les conditions d'accès applicables.","incorrect":"La bonne réponse est la deuxième. La transmission doit répondre à une finalité appropriée et respecter les conditions d'accès applicables."}},"m06-q5":{"type":"choix-unique","objectif":"os6-6","notation":{"formative":false,"points":1},"consigne":"Pourquoi préciser la date de référence d'un tableau d'effectifs ?","choix":[{"id":"a","texte":"Pour rendre le fichier plus volumineux."},{"id":"b","texte":"Pour remplacer toutes les procédures."},{"id":"c","texte":"Pour permettre aux utilisateurs de comprendre à quelle période correspondent les chiffres."}],"reponse":"c","explication":{"correct":"La date de référence fait partie des informations qui aident à interpréter correctement un ensemble de données.","incorrect":"La bonne réponse est la troisième. La date de référence fait partie des informations qui aident à interpréter correctement un ensemble de données."}}},"synthese":["**Rechercher** : avant de créer une donnée ou un fichier, vérifier ce qui existe déjà.","**Vérifier** : contrôler les informations nécessaires et utiliser les sources appropriées.","**Respecter** : utiliser les formats, identifiants, référentiels et procédures applicables.","**Partager** : transmettre les données dans un cadre autorisé et adapté aux besoins.","**Documenter et signaler** : faciliter la compréhension des informations et faire remonter les anomalies."],"fiche":{"titre":"Les 5 réflexes pour bien gérer les données","introduction":"Bien gérer les données ne demande pas de maîtriser des outils complexes : cela commence par des réflexes simples, adaptés à ton métier et aux règles de l'établissement.","reflexes":[{"icone":"🔎","titre":"1. Rechercher","texte":"Avant de créer une donnée ou un fichier, je vérifie ce qui existe déjà.","question":"Cette information existe-t-elle déjà dans une source appropriée ?"},{"icone":"✔","titre":"2. Vérifier","texte":"Je contrôle les informations nécessaires et j'utilise les sources appropriées.","question":"Ma source est-elle fiable et à jour ?"},{"icone":"📏","titre":"3. Respecter","texte":"J'utilise les formats, identifiants, référentiels et procédures applicables.","question":"Ma saisie suit-elle le format et les valeurs de référence prévus ?"},{"icone":"🔐","titre":"4. Partager","texte":"Je transmets les données dans un cadre autorisé et adapté au besoin.","question":"Le destinataire en a-t-il besoin, et en a-t-il le droit ?"},{"icone":"📝","titre":"5. Documenter et signaler","texte":"Je facilite la compréhension des informations et je fais remonter les anomalies.","question":"Un collègue comprendrait-il ces données sans moi ? Ai-je signalé ce qui ne va pas ?"}],"rappel":"En cas de doute, je consulte les procédures et les interlocuteurs compétents."}},"m07":{"id":"m07","numero":7,"titre":"Validation et consolidation des acquis","sousTitre":"Mettre en pratique les principes essentiels de la gouvernance de la donnée.","slugArchive":"validation-consolidation","duree":7,"statutContenu":"proposition - à valider (seuil, tentatives et reconnaissance à arbitrer)","objectif":"Vérifier que tu as compris les notions essentielles de la gouvernance de la donnée et que tu sais reconnaître les bonnes pratiques dans des situations professionnelles simples.","objectifsSpecifiques":[{"id":"os7-1","texte":"Reconnaître ce qu'est une donnée."},{"id":"os7-2","texte":"Comprendre qu'une donnée peut être utilisée dans plusieurs services."},{"id":"os7-3","texte":"Identifier les conséquences d'une donnée incorrecte ou mal structurée."},{"id":"os7-4","texte":"Reconnaître l'utilité d'un identifiant et d'un référentiel."},{"id":"os7-5","texte":"Identifier les conditions essentielles d'un partage responsable."},{"id":"os7-6","texte":"Comprendre les rôles de la gouvernance et de la gestion opérationnelle."},{"id":"os7-7","texte":"Choisir les bons réflexes professionnels face à une situation."}],"validation":{"navigation":"sequentielle","leconsObligatoires":true,"evaluation":"m07-mission","seuilReussite":70,"scoreRetenu":"meilleur","libelleEchec":"Seuil non atteint"},"lecons":[{"id":"m07-intro","type":"lecon","titre":"À toi de jouer : une université, des données, des décisions","blocs":[{"type":"texte","texte":"Tu as découvert comment les données sont créées, utilisées, vérifiées, partagées et organisées au sein de l'université.\n\nDans cette dernière activité, tu vas rencontrer plusieurs situations inspirées du quotidien des services. Pour chacune, choisis la réponse qui te semble la plus adaptée."},{"type":"texte","titre":"Comment se déroule la mission","texte":"- **Sept situations**, une seule réponse attendue pour chacune.\n- **Environ 5 à 8 minutes**, sans chronomètre.\n- Tu peux revenir sur une question et modifier ta réponse tant que tu n'as pas validé.\n- **Le résultat et les corrections** s'affichent après la validation de tes sept réponses.\n- Seuil de réussite retenu pour ce prototype : **70 %**, soit 5 bonnes réponses sur 7. Tu peux recommencer la mission.\n- Si tu t'interromps, tes réponses sont conservées : tu reprendras là où tu en étais."},{"type":"aretenir","texte":"L'objectif n'est pas de devenir expert des données, mais de reconnaître les principes essentiels et les bons réflexes professionnels."}]},{"id":"m07-mission","type":"evaluation","titre":"Mission finale","surtitre":"Mission finale","libelleAcces":"Commencer la mission finale","libelleRecommencer":"Recommencer la mission","libelleValider":"Valider mes réponses","presentation":"une-par-une","correction":"differee","introduction":"Sept situations, une à la fois. Choisis la réponse qui te semble la plus adaptée : tu pourras revenir en arrière avant de valider, et découvrir ensuite les corrections.","activites":["m07-q1","m07-q2","m07-q3","m07-q4","m07-q5","m07-q6","m07-q7"],"messageSeuilAtteint":"Bravo ! Tu as compris les principes essentiels de la gouvernance de la donnée. Tu sais désormais reconnaître l'importance de la qualité, de la structuration, du partage responsable et des règles communes. Ces connaissances t'aideront à contribuer, à ton niveau, à une meilleure gestion collective des données.","messageSeuilNonAtteint":"Tu as terminé cette tentative. Certaines notions méritent d'être revues : tu peux consulter les corrections et revenir sur les modules correspondants avant de recommencer.","ecranFinal":{"titre":"Ce que je retiens de la gouvernance de la donnée","messages":[{"titre":"La donnée est partout.","texte":"Je manipule des données dans mes activités quotidiennes, même sans utiliser d'outils spécialisés."},{"titre":"Une donnée peut avoir plusieurs usages.","texte":"Une information créée dans un service peut être utile ailleurs."},{"titre":"La qualité facilite le travail collectif.","texte":"Une donnée exacte, cohérente, suffisamment complète et actualisée est plus facile à exploiter."},{"titre":"Le partage doit être responsable.","texte":"Je tiens compte des finalités, des besoins, des droits d'accès et des règles applicables."},{"titre":"La gouvernance organise les responsabilités.","texte":"Elle définit un cadre collectif auquel les services métiers, les responsables et les agents contribuent."},{"titre":"Je peux agir à mon niveau.","texte":"Je recherche, vérifie, respecte les règles, partage dans le bon cadre, documente et signale les anomalies."}],"conclusion":"La gouvernance de la donnée n'est pas uniquement une affaire de spécialistes.\n\nElle repose sur une organisation commune et sur des pratiques professionnelles auxquelles chacun peut contribuer."}}],"activites":{"m07-q1":{"type":"choix-unique","objectif":"os7-1","notation":{"formative":false,"points":1},"consigne":"Un technicien de maintenance renseigne dans une application la date du dernier contrôle d'un équipement. Cette information est-elle une donnée ?","choix":[{"id":"a","texte":"Non, car elle ne concerne pas une personne."},{"id":"b","texte":"Oui, car il s'agit d'une information enregistrée et exploitable."},{"id":"c","texte":"Non, car seules les informations contenues dans Excel sont des données."}],"reponse":"b","explication":{"correct":"Une donnée peut concerner une personne, un équipement, un bâtiment, une opération ou une activité. Elle n'est pas nécessairement personnelle ni numérique.","incorrect":"Une donnée peut concerner une personne, un équipement, un bâtiment, une opération ou une activité. Elle n'est pas nécessairement personnelle ni numérique."},"remediation":{"module":"m01","notion":"Reconnaître une donnée","resume":"Une donnée est une information enregistrée et exploitable. Elle peut décrire une personne, mais aussi un équipement, un bâtiment ou une activité, sur papier comme dans une application."}},"m07-q2":{"type":"choix-unique","objectif":"os7-2","notation":{"formative":false,"points":1},"consigne":"Le service RH met à jour l'affectation d'un agent. Pourquoi cette information peut-elle être importante au-delà du service RH ?","choix":[{"id":"a","texte":"Parce que certains autres services peuvent en avoir besoin dans le cadre de leurs missions."},{"id":"b","texte":"Parce que tous les services doivent pouvoir consulter librement le dossier complet de l'agent."},{"id":"c","texte":"Parce qu'une donnée RH ne peut être utilisée qu'une seule fois."}],"reponse":"a","explication":{"correct":"Une donnée peut être utilisée dans plusieurs activités, selon les besoins et les autorisations. Une information mal actualisée peut donc produire des conséquences dans d'autres services.","incorrect":"Une donnée peut être utilisée dans plusieurs activités, selon les besoins et les autorisations. Une information mal actualisée peut donc produire des conséquences dans d'autres services."},"remediation":{"module":"m02","notion":"Les usages multiples d'une donnée","resume":"Une information créée dans un service sert souvent à d'autres, selon leurs besoins et leurs autorisations : une mise à jour oubliée a des effets au-delà du service qui la gère."}},"m07-q3":{"type":"choix-unique","objectif":"os7-3","notation":{"formative":false,"points":1},"consigne":"Un service reçoit un tableau contenant des dates saisies dans plusieurs formats et des noms de structures non homogènes. Quel problème cela peut-il provoquer ?","choix":[{"id":"a","texte":"Aucun, puisque le fichier s'ouvre correctement."},{"id":"b","texte":"Les données risquent d'être plus difficiles à comparer, trier ou réutiliser."},{"id":"c","texte":"Le fichier devient automatiquement inutilisable par tous les logiciels."}],"reponse":"b","explication":{"correct":"Des formats et des nomenclatures homogènes facilitent les contrôles, les rapprochements et la réutilisation des données.","incorrect":"Des formats et des nomenclatures homogènes facilitent les contrôles, les rapprochements et la réutilisation des données."},"remediation":{"module":"m03","notion":"Qualité et structuration des données","resume":"Des formats de date et des libellés homogènes permettent de trier, comparer, contrôler et réutiliser les données. Un fichier qui s'ouvre n'est pas forcément exploitable."}},"m07-q4":{"type":"choix-unique","objectif":"os7-4","notation":{"formative":false,"points":1},"consigne":"Deux étudiants portent le même nom et le même prénom. Quelle démarche permet de mieux distinguer leurs dossiers dans le système de scolarité ?","choix":[{"id":"a","texte":"Utiliser l'identifiant étudiant individuel prévu par le système."},{"id":"b","texte":"Choisir celui qui apparaît en premier dans la liste."},{"id":"c","texte":"Ajouter un surnom inventé."}],"reponse":"a","explication":{"correct":"Un identifiant stable et unique dans son périmètre permet de distinguer des enregistrements ayant des informations similaires.","incorrect":"Un identifiant stable et unique dans son périmètre permet de distinguer des enregistrements ayant des informations similaires."},"remediation":{"module":"m03","notion":"Identifiants et référentiels","resume":"Un identifiant unique et stable distingue deux enregistrements qui se ressemblent ; un référentiel fixe les valeurs communes à utiliser par tous."}},"m07-q5":{"type":"choix-unique","objectif":"os7-5","notation":{"formative":false,"points":1},"consigne":"Un service demande un fichier nominatif contenant des informations administratives individuelles sur les agents. Le besoin n'est pas précisé. Quelle attitude adopter ?","choix":[{"id":"a","texte":"Transmettre immédiatement le fichier puisqu'il s'agit d'un service interne."},{"id":"b","texte":"Refuser définitivement toute possibilité de partage."},{"id":"c","texte":"Vérifier la finalité, les données nécessaires et les conditions d'accès avant toute transmission."}],"reponse":"c","explication":{"correct":"Le partage doit respecter une finalité appropriée, les autorisations et les règles applicables. Une donnée personnelle n'est pas automatiquement interdite de partage, mais sa transmission doit être encadrée.","incorrect":"Le partage doit respecter une finalité appropriée, les autorisations et les règles applicables. Une donnée personnelle n'est pas automatiquement interdite de partage, mais sa transmission doit être encadrée."},"remediation":{"module":"m04","notion":"Le partage responsable","resume":"Partager n'est ni tout transmettre, ni tout refuser : on vérifie la finalité, les données vraiment nécessaires, les droits d'accès et les règles applicables."}},"m07-q6":{"type":"choix-unique","objectif":"os7-6","notation":{"formative":false,"points":1},"consigne":"Plusieurs services souhaitent utiliser une même nomenclature pour identifier les bâtiments universitaires. Qui doit organiser la définition et la validation de cette règle commune ?","choix":[{"id":"a","texte":"Un agent isolé, sans consulter les autres services."},{"id":"b","texte":"Les responsables métiers et acteurs de gouvernance compétents, selon l'organisation établie."},{"id":"c","texte":"Un logiciel, sans intervention humaine."}],"reponse":"b","explication":{"correct":"La gouvernance repose sur des règles, des responsabilités et des décisions collectives. Les métiers apportent leur connaissance des besoins et des usages.","incorrect":"La gouvernance repose sur des règles, des responsabilités et des décisions collectives. Les métiers apportent leur connaissance des besoins et des usages."},"remediation":{"module":"m05","notion":"Gouvernance et responsabilités","resume":"La gouvernance organise les règles communes, les responsabilités et les décisions ; les services métiers y apportent leur connaissance des besoins, la gestion opérationnelle les applique."}},"m07-q7":{"type":"choix-unique","objectif":"os7-7","notation":{"formative":false,"points":1},"consigne":"Tu dois créer un nouveau tableau de suivi. Un collègue t'indique qu'une source d'information institutionnelle pourrait déjà exister. Quel est le meilleur réflexe ?","choix":[{"id":"a","texte":"Créer un nouveau fichier sans vérification."},{"id":"b","texte":"Vérifier si la source existante répond au besoin et dans quelles conditions tu peux l'utiliser."},{"id":"c","texte":"Copier plusieurs anciens tableaux sans contrôler leur actualité."}],"reponse":"b","explication":{"correct":"Rechercher les données existantes permet de limiter les copies inutiles, les versions contradictoires et les corrections répétées.","incorrect":"Rechercher les données existantes permet de limiter les copies inutiles, les versions contradictoires et les corrections répétées."},"remediation":{"module":"m06","notion":"Les bons réflexes professionnels","resume":"Rechercher ce qui existe, vérifier, respecter les règles, partager dans le bon cadre, documenter et signaler les anomalies."}}}}}};
